QT_ISI(28,{"5105":["(Sesungguhnya Allah telah mendengar perkataan wanita yang mengajukan gugatan kepada kamu) yakni seorang wanita yang melapor kepadamu, hai nabi (tentang suaminya) yang telah mengucapkan kata-kata zihar kepadanya. Suami wanita itu berkata kepadanya, \"Kamu menurutku bagaikan punggung ibuku.\" Lalu wanita itu menanyakan hal tersebut kepada Nabi saw., maka beliau menjawab bahwa dia haram atas suaminya. Hal ini sesuai dengan tradisi yang berlaku di kalangan mereka, bahwa zihar itu akibatnya adalah perpisahan untuk selama-lamanya. Wanita yang dimaksud bernama Khaulah binti Tsa'labah, sedangkan suaminya bernama Aus bin Shamit (dan mengadukan halnya kepada Allah) yakni tentang keadaannya yang tidak mempunyai orang tua dan famili yang terdekat, serta keadaan ekonominya yang serba kekurangan, di samping itu ia menanggung beban anak-anaknya yang masih kecil-kecil; apabila anak-anaknya dibawa oleh suaminya, niscaya mereka akan tersia-sia dan tak terurus lagi keadaannya tetapi apabila anak-anak itu di bawah pemeliharaannya, niscaya mereka akan kelaparan. (Dan Allah mendengar soal jawab antara kamu berdua) dialog kamu berdua. (Sesungguhnya Allah Maha Mendengar lagi Maha Melihat) artinya Maha Mengetahui.",[["قَدْ","Sesungguhnya"],["سَمِعَ","Allah telah mendengar"],["ٱللَّهُ","Allah telah mendengar"],["قَوْلَ","(the) ucapan"],["ٱلَّتِى","(daripada satu) siapa"],["تُجَـٰدِلُكَ","perselisihan dengan kamu"],["فِى","tentang"],["زَوْجِهَا","suaminya"],["وَتَشْتَكِىٓ","dan dia mengarahkan aduannya"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَٱللَّهُ","Dan Allah"],["يَسْمَعُ","mendengar"],["تَحَاوُرَكُمَآ ۚ","(the) dialog kamu berdua"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَمِيعٌۢ","(adalah) Yang Maha Mendengar"],["بَصِيرٌ","Maha Melihat"]]],"5106":["(Orang-orang yang menzihar) asal kata yazhzhahharuuna adalah yatazhahharuuna, kemudian huruf ta diidgamkan ke dalam huruf zha sehingga jadilah yazhzhahharuuna. Akan tetapi menurut suatu qiraat dibaca dengan memakai huruf alif di antara huruf zha dan ha, sehingga bacaannya menjadi yazhaaharuuna. Menurut qiraat lainnya dibaca seperti wazan yuqaatiluuna, yakni menjadi yuzhaahiruuna. Lafal yang sama pada ayat berikutnya berlaku pula ketentuan ini (istrinya di antara kalian, padahal tiadalah istri mereka itu ibu mereka. Ibu-ibu mereka tidak lain hanyalah wanita-wanita) lafal allaaiy dapat dibaca dengan memakai huruf ya dan dapat pula dibaca tanpa ya (yang melahirkan mereka. Sesungguhnya mereka) dengan melakukan zihar itu (sungguh-sungguh mengucapkan suatu perkataan yang mungkar dan dusta). (Dan sesungguhnya Allah Maha Pemaaf lagi Maha Pengampun) kepada orang yang melakukan zihar dengan pembayaran kifarat.",[["ٱلَّذِينَ","Orang yang"],["يُظَـٰهِرُونَ","melafazkan zihar"],["مِنكُم","antara kamu"],["مِّن","[dari]"],["نِّسَآئِهِم","(kepada) isteri-isteri mereka"],["مَّا","tidak"],["هُنَّ","mereka"],["أُمَّهَـٰتِهِمْ ۖ","(adalah) ibu mereka"],["إِنْ","Tidak"],["أُمَّهَـٰتُهُمْ","(adalah) ibu mereka"],["إِلَّا","kecuali"],["ٱلَّـٰٓـِٔى","orang yang"],["وَلَدْنَهُمْ ۚ","melahirkan mereka"],["وَإِنَّهُمْ","Dan sesungguhnya, mereka"],["لَيَقُولُونَ","pasti berkata"],["مُنكَرًۭا","satu kejahatan"],["مِّنَ","[daripada]"],["ٱلْقَوْلِ","[the] perkataan"],["وَزُورًۭا ۚ","dan pembohongan"],["وَإِنَّ","Tetapi sesungguhnya"],["ٱللَّهَ","Allah"],["لَعَفُوٌّ","(adalah) pasti, Maha Pengampun"],["غَفُورٌۭ","Selalu Memaafkan"]]],"5107":["(Dan orang-orang yang menzihar istri mereka, kemudian mereka hendak menarik kembali apa yang mereka ucapkan) tentang zihar ini, seumpama dia bersikap berbeda dengan apa yang telah dikatakannya itu, yaitu dengan cara tetap memegang istri yang diziharnya. Sedangkan perbuatan ini jelas bertentangan dengan maksud tujuan daripada perkataan zihar, yaitu menggambarkan istri dengan sifat yang menjadikannya haram bagi dia (maka memerdekakan seorang budak) maksudnya wajib atasnya memerdekakan seorang budak (sebelum kedua suami istri itu bercampur) bersetubuh. (Demikianlah yang diajarkan kepada kalian, dan Allah Maha Mengetahui apa yang kalian kerjakan).",[["وَٱلَّذِينَ","Dan orang yang"],["يُظَـٰهِرُونَ","melafazkan zihar"],["مِن","[dari]"],["نِّسَآئِهِمْ","(kepada) isteri-isteri mereka"],["ثُمَّ","kemudian"],["يَعُودُونَ","pergi balik"],["لِمَا","atas apa"],["قَالُوا۟","mereka berkata"],["فَتَحْرِيرُ","kemudian membebaskan"],["رَقَبَةٍۢ","(dari) seorang hamba"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَتَمَآسَّا ۚ","mereka bersentuhan antara satu sama lain"],["ذَٰلِكُمْ","Itu"],["تُوعَظُونَ","kamu dinasihatkan"],["بِهِۦ ۚ","kepadanya"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"5108":["(Maka barang siapa yang tidak mendapatkan) budak (maka wajib atasnya berpuasa dua bulan berturut-turut, sebelum keduanya bercampur. Maka siapa yang tidak mampu) melakukan puasa (memberi makan enam puluh orang miskin) diwajibkan atasnya, yakni sebelum keduanya bercampur kembali sebagai suami istri; untuk tiap-tiap orang miskin satu mudd makanan pokok negeri orang yang bersangkutan. Kesimpulan hukum ini berdasarkan pemahaman menyamakan pengertian yang mutlak dengan yang muqayyad. (Demikianlah) keringanan ini dengan memakai kifarat (supaya kalian beriman kepada Allah dan Rasul-Nya. Dan itulah) yakni hukum-hukum tersebut (batasan-batasan Allah, dan bagi orang-orang yang ingkar) kepada batasan-batasan atau hukum-hukum Allah itu (azab yang sangat pedih) atau siksaan yang amat menyakitkan.",[["فَمَن","Kemudian sesiapa sahaja"],["لَّمْ","tidak"],["يَجِدْ","cari"],["فَصِيَامُ","kemudian berpuasa"],["شَهْرَيْنِ","(selama) dua bulan"],["مُتَتَابِعَيْنِ","berturut-turut"],["مِن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَتَمَآسَّا ۖ","mereka berdua menyentuh antara satu sama lain"],["فَمَن","Tetapi (dia) yang"],["لَّمْ","tidak"],["يَسْتَطِعْ","mampu"],["فَإِطْعَامُ","kemudian (yang) memberi makan"],["سِتِّينَ","(daripada) enam puluh"],["مِسْكِينًۭا ۚ","yang memerlukan"],["ذَٰلِكَ","Itu"],["لِتُؤْمِنُوا۟","supaya kamu beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ ۚ","dan Rasul-Nya"],["وَتِلْكَ","dan ini"],["حُدُودُ","(adalah) had"],["ٱللَّهِ ۗ","(milik) Allah"],["وَلِلْكَـٰفِرِينَ","dan bagi orang-orang kafir"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌ","yang pedih"]]],"5109":["(Sesungguhnya orang-orang yang menentang) orang-orang yang melawan (Allah dan Rasul-Nya pasti mendapat kehinaan) mereka pasti akan memperoleh kehinaan (sebagaimana orang-orang yang sebelum mereka telah mendapat kehinaan) karena mereka menentang rasul-rasul mereka. (Sesungguhnya Kami telah menurunkan ayat-ayat yang jelas) yang menunjukkan kebenaran Rasul. (Dan bagi orang-orang yang kafir) yang ingkar kepada ayat-ayat itu (ada azab yang menghinakan) yaitu siksaan yang membuat mereka hina.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُحَآدُّونَ","menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["كُبِتُوا۟","(akan) terhina"],["كَمَا","seperti"],["كُبِتَ","telah dimalukan"],["ٱلَّذِينَ","mereka"],["مِن","sebelum mereka"],["قَبْلِهِمْ ۚ","sebelum mereka"],["وَقَدْ","Dan sungguh"],["أَنزَلْنَآ","Kami telah menurunkan"],["ءَايَـٰتٍۭ","ayat-ayat"],["بَيِّنَـٰتٍۢ ۚ","yang nyata"],["وَلِلْكَـٰفِرِينَ","Dan bagi orang-orang kafir"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"5110":["(Pada hari ketika mereka semuanya dibangkitkan Allah lalu diberitakan-Nya kepada mereka apa yang telah mereka kerjakan. Allah menghitung amal perbuatan itu, padahal mereka telah melupakannya. Dan Allah Maha Menyaksikan segala sesuatu).",[["يَوْمَ","(Pada) Hari"],["يَبْعَثُهُمُ","(apabila) Allah akan membangkitkan mereka"],["ٱللَّهُ","(apabila) Allah akan membangkitkan mereka"],["جَمِيعًۭا","semua"],["فَيُنَبِّئُهُم","dan maklumkan kepada mereka"],["بِمَا","tentang apa"],["عَمِلُوٓا۟ ۚ","mereka lakukan"],["أَحْصَىٰهُ","Allah telah mencatatnya"],["ٱللَّهُ","Allah telah mencatatnya"],["وَنَسُوهُ ۚ","sedangkan mereka melupakannya"],["وَٱللَّهُ","Dan Allah"],["عَلَىٰ","(sudah) tamat"],["كُلِّ","semua"],["شَىْءٍۢ","benda"],["شَهِيدٌ","seorang Saksi"]]],"5111":["(Tidakkah kamu perhatikan) tidakkah kamu ketahui (bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan apa yang ada di bumi? Tiada pembicaraan rahasia antara tiga orang, melainkan Dialah yang keempatnya) yakni melalui ilmu-Nya. (Dan tiada pembicaraan antara lima orang, melainkan Dialah yang keenamnya. Dan tiada pula pembicaraan antara jumlah yang kurang dari itu atau lebih banyak, melainkan Dia ada bersama mereka di mana pun mereka berada. Kemudian Dia akan memberitakan kepada mereka pada hari kiamat apa yang telah mereka kerjakan. Sesungguhnya Allah Maha Mengetahui segala sesuatu).",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۖ","bumi"],["مَا","Tidak"],["يَكُونُ","ada"],["مِن","sebarang"],["نَّجْوَىٰ","penasihat rahsia"],["ثَلَـٰثَةٍ","(daripada) tiga"],["إِلَّا","tetapi"],["هُوَ","dia (adalah)"],["رَابِعُهُمْ","(yang) keempat daripada mereka"],["وَلَا","dan bukan"],["خَمْسَةٍ","lima"],["إِلَّا","tetapi"],["هُوَ","dia (adalah)"],["سَادِسُهُمْ","(yang) keenam daripada mereka"],["وَلَآ","dan bukan"],["أَدْنَىٰ","kurang"],["مِن","daripada"],["ذَٰلِكَ","bahawa"],["وَلَآ","dan bukan"],["أَكْثَرَ","lebih"],["إِلَّا","tetapi"],["هُوَ","Dia"],["مَعَهُمْ","(ada) bersama mereka"],["أَيْنَ","di mana sahaja"],["مَا","di mana sahaja"],["كَانُوا۟ ۖ","mereka adalah"],["ثُمَّ","Kemudian"],["يُنَبِّئُهُم","Dia akan memberitahu mereka"],["بِمَا","tentang apa"],["عَمِلُوا۟","mereka lakukan"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌ","Maha Mengetahui"]]],"5112":["(Apakah tidak kamu perhatikan) apakah tidak kamu lihat (orang-orang yang telah dilarang mengadakan pembicaraan rahasia, kemudian mereka kembali mengerjakan larangan itu dan mereka mengadakan pembicaraan rahasia untuk berbuat dosa, permusuhan dan durhaka kepada rasul) mereka adalah orang-orang Yahudi; Nabi saw. telah melarang mereka dari pembicaraan rahasia yang dahulu sering mereka lakukan. Pembicaraan rahasia mereka itu dalam rangka merencanakan tindakan sabotase terhadap kaum mukminin, dimaksud supaya mereka dapat menanamkan keraguan dalam hati kaum mukminin. (Dan apabila mereka datang kepadamu, mereka mengucapkan salam kepadamu) hai nabi (dengan memberi salam yang bukan sebagai yang ditentukan Allah untukmu) yaitu perkataan mereka, \"As-Sammu 'alaika,\" yakni kematian atasmu. (Dan mereka mengatakan pada diri mereka sendiri, \"Mengapa tidak) kenapa tidak (diturunkan azab atas kami oleh Allah disebabkan apa yang kita katakan itu?\") Yakni salam penghinaan yang kami katakan itu, kalau begitu dia bukanlah seorang nabi, sekalipun dia adalah nabi. (Cukuplah bagi mereka neraka Jahanam yang akan mereka masuki Dan seburuk-buruk tempat kembali itu) adalah neraka Jahanam.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["إِلَى","[ke]"],["ٱلَّذِينَ","orang yang"],["نُهُوا۟","telah dilarang"],["عَنِ","daripada"],["ٱلنَّجْوَىٰ","nasihat rahsia"],["ثُمَّ","kemudian"],["يَعُودُونَ","mereka balik"],["لِمَا","ke apa"],["نُهُوا۟","mereka dilarang"],["عَنْهُ","daripada [itu]"],["وَيَتَنَـٰجَوْنَ","dan mereka mengadakan nasihat rahsia"],["بِٱلْإِثْمِ","untuk dosa"],["وَٱلْعُدْوَٰنِ","dan pencerobohan"],["وَمَعْصِيَتِ","dan kemaksiatan"],["ٱلرَّسُولِ","(kepada) Rasul"],["وَإِذَا","Dan apabila"],["جَآءُوكَ","mereka datang kepada kamu"],["حَيَّوْكَ","mereka memberi salam kepada kamu"],["بِمَا","dengan apa"],["لَمْ","tidak"],["يُحَيِّكَ","salam kamu"],["بِهِ","dengan itu"],["ٱللَّهُ","Allah"],["وَيَقُولُونَ","dan mereka berkata"],["فِىٓ","antara"],["أَنفُسِهِمْ","diri mereka"],["لَوْلَا","Mengapa (tidak) tidak"],["يُعَذِّبُنَا","Allah menghukum kita"],["ٱللَّهُ","Allah menghukum kita"],["بِمَا","bagi apa"],["نَقُولُ ۚ","kita cakap"],["حَسْبُهُمْ","Memadai (untuk) mereka"],["جَهَنَّمُ","(ialah) Neraka"],["يَصْلَوْنَهَا ۖ","mereka akan terbakar di dalamnya"],["فَبِئْسَ","dan yang paling teruk ialah"],["ٱلْمَصِيرُ","destinasi"]]],"5113":["(Hai orang-orang yang beriman, apabila kalian mengadakan pembicaraan rahasia, janganlah kalian membicarakan tentang berbuat dosa, permusuhan dan durhaka kepada rasul. Dan bicarakanlah tentang berbuat kebaikan dan takwa. Dan bertakwalah kepada Allah yang kepada-Nya kalian akan dikembalikan).",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِذَا","Apabila"],["تَنَـٰجَيْتُمْ","kamu memegang peguam rahsia"],["فَلَا","maka (buat) jangan"],["تَتَنَـٰجَوْا۟","memegang peguam rahsia"],["بِٱلْإِثْمِ","untuk dosa"],["وَٱلْعُدْوَٰنِ","dan pencerobohan"],["وَمَعْصِيَتِ","dan kemaksiatan"],["ٱلرَّسُولِ","(kepada) Rasul"],["وَتَنَـٰجَوْا۟","tetapi memegang nasihat rahsia"],["بِٱلْبِرِّ","untuk kebenaran"],["وَٱلتَّقْوَىٰ ۖ","dan takwa"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["ٱلَّذِىٓ","yang Esa"],["إِلَيْهِ","kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"5114":["(Sesungguhnya pembicaraan rahasia itu) yakni yang membicarakan berbuat dosa dan yang sejenisnya (adalah dari setan) melalui bujuk rayuannya (supaya orang-orang yang beriman itu berduka cita, sedangkan tiadalah) pembicaraan itu (dapat memberikan mudarat kepada mereka barang sedikit pun kecuali dengan izin Allah) atas kehendak-Nya (dan kepada Allah-lah hendaknya orang-orang yang beriman bertawakal).",[["إِنَّمَا","Hanya"],["ٱلنَّجْوَىٰ","penasihat rahsia"],["مِنَ","(adalah) daripada"],["ٱلشَّيْطَـٰنِ","syaitan"],["لِيَحْزُنَ","supaya dia berduka"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَلَيْسَ","tetapi tidak"],["بِضَآرِّهِمْ","dia (boleh) membahayakan mereka"],["شَيْـًٔا","(dalam) apa-apa"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin Allah"],["ٱللَّهِ ۚ","dengan izin Allah"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","hendaklah meletakkan amanah (mereka)."],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"5115":["(Hai orang-orang yang beriman, apabila dikatakan kepada kalian, \"Berlapang-lapanglah) berluas-luaslah (dalam majelis\") yaitu majelis tempat Nabi saw. berada, dan majelis zikir sehingga orang-orang yang datang kepada kalian dapat tempat duduk. Menurut suatu qiraat lafal al-majaalis dibaca al-majlis dalam bentuk mufrad (maka lapangkanlah, niscaya Allah akan memberi kelapangan untuk kalian) di surga nanti. (Dan apabila dikatakan, \"Berdirilah kalian\") untuk melakukan salat dan hal-hal lainnya yang termasuk amal-amal kebaikan (maka berdirilah) menurut qiraat lainnya kedua-duanya dibaca fansyuzuu dengan memakai harakat damah pada huruf Syinnya (niscaya Allah akan meninggikan orang-orang yang beriman di antara kalian) karena ketaatannya dalam hal tersebut (dan) Dia meninggikan pula (orang-orang yang diberi ilmu pengetahuan beberapa derajat) di surga nanti. (Dan Allah Maha Mengetahui apa yang kalian kerjakan).",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِذَا","Apabila"],["قِيلَ","dikatakan"],["لَكُمْ","kepada kamu"],["تَفَسَّحُوا۟","Buat ruang"],["فِى","dalam"],["ٱلْمَجَـٰلِسِ","perhimpunan"],["فَٱفْسَحُوا۟","kemudian beri ruang"],["يَفْسَحِ","Allah akan memberi kelapangan"],["ٱللَّهُ","Allah akan memberi kelapangan"],["لَكُمْ ۖ","bagi kamu"],["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["ٱنشُزُوا۟","Bangkitlah"],["فَٱنشُزُوا۟","kemudian bangkit"],["يَرْفَعِ","Allah akan bangkitkan"],["ٱللَّهُ","Allah akan bangkitkan"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["مِنكُمْ","antara kamu"],["وَٱلَّذِينَ","dan orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["دَرَجَـٰتٍۢ ۚ","(dalam) darjah"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"5116":["(Hai orang-orang yang beriman, apabila kalian mengadakan pembicaraan khusus dengan rasul) yakni kalian bermaksud untuk melakukannya dengan dia (hendaklah kalian mengeluarkan sebelum pembicaraan kalian itu) sebelum pembicaraan khusus itu diadakan (sedekah. Yang demikian itu adalah lebih baik bagi kalian dan lebih bersih) artinya lebih membersihkan dosa-dosa kalian (jika kalian tidak menemukan) apa yang kalian sedekahkan (maka sesungguhnya Allah Maha Pengampun) terhadap pembicaraan khusus yang akan kalian lakukan itu (lagi Maha Penyayang) terhadap kalian. Makna yang dimaksud, tiada dosa bagi kalian untuk melakukan pembicaraan khusus itu sekalipun tanpa sedekah.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوٓا۟","Wahai orang yang beriman"],["إِذَا","Apabila"],["نَـٰجَيْتُمُ","kamu berunding secara peribadi"],["ٱلرَّسُولَ","Rasul"],["فَقَدِّمُوا۟","kemudian menawarkan"],["بَيْنَ","sebelum"],["يَدَىْ","sebelum"],["نَجْوَىٰكُمْ","perundingan peribadi kamu"],["صَدَقَةًۭ ۚ","amal jariah"],["ذَٰلِكَ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["وَأَطْهَرُ ۚ","dan lebih suci"],["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["تَجِدُوا۟","kamu dapati"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"5117":["(Apakah kalian takut) dapat dibaca tahqiq dan tashil, artinya merasa takut dari (karena kamu memberikan sedekah sebelum pembicaraan dengan rasul) karena takut menjadi miskin. (Maka jika kalian tiada memperbuatnya) artinya tidak memberikan sedekah (dan Allah telah memberi tobat kepada kalian) maksudnya Dia telah membebaskan kalian dari sedekah itu (maka dirikanlah salat, tunaikanlah zakat dan taatlah kepada Allah dan Rasul-Nya) yakni terus-meneruslah kalian melakukan hal-hal tersebut (dan Allah Maha Mengetahui apa yang kalian kerjakan).",[["ءَأَشْفَقْتُمْ","Adakah kamu takut"],["أَن","kepada"],["تُقَدِّمُوا۟","tawaran"],["بَيْنَ","sebelum"],["يَدَىْ","sebelum"],["نَجْوَىٰكُمْ","perundingan peribadi kamu"],["صَدَقَـٰتٍۢ ۚ","badan amal"],["فَإِذْ","Kemudian apabila"],["لَمْ","kamu tidak"],["تَفْعَلُوا۟","kamu tidak"],["وَتَابَ","dan Allah telah mengampuni"],["ٱللَّهُ","dan Allah telah mengampuni"],["عَلَيْكُمْ","kamu"],["فَأَقِيمُوا۟","kemudian menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["وَأَطِيعُوا۟","dan taat"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ ۚ","dan Rasul-Nya"],["وَٱللَّهُ","Dan Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"5118":["(Tidakkah kamu perhatikan) tidakkah kamu melihat (orang-orang yang menjadikan teman) mereka adalah kaum munafik (suatu kaum) yang dimaksud adalah orang-orang Yahudi (yang dimurkai Allah? Orang-orang itu bukan) yakni orang-orang munafik itu bukan (dari golongan kalian) orang-orang mukmin (dan bukan pula dari golongan mereka) bukan dari kalangan orang-orang Yahudi akan tetapi mereka adalah orang-orang yang bermuka dua. (Dan mereka bersumpah untuk menguatkan kebohongan) yakni perkataan mereka bahwa sesungguhnya mereka adalah orang-orang beriman (sedang mereka mengetahui) bahwa dalam hal ini mereka berdusta belaka.",[["۞ أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["إِلَى","[ke]"],["ٱلَّذِينَ","orang yang"],["تَوَلَّوْا۟","ambil sebagai sekutu"],["قَوْمًا","suatu kaum"],["غَضِبَ","kemarahan"],["ٱللَّهُ","(milik) Allah"],["عَلَيْهِم","(ada) atas mereka"],["مَّا","Mereka (adalah) tidak"],["هُم","Mereka (adalah) tidak"],["مِّنكُمْ","daripada kamu"],["وَلَا","dan bukan"],["مِنْهُمْ","daripada mereka"],["وَيَحْلِفُونَ","dan mereka bersumpah"],["عَلَى","kepada"],["ٱلْكَذِبِ","pembohongan itu"],["وَهُمْ","sedangkan mereka"],["يَعْلَمُونَ","mengetahui"]]],"5119":["(Allah telah menyediakan bagi mereka azab yang sangat keras, sesungguhnya amat buruklah apa yang telah mereka kerjakan) dari perbuatan-perbuatan maksiat.",[["أَعَدَّ","Allah dah sediakan"],["ٱللَّهُ","Allah dah sediakan"],["لَهُمْ","bagi mereka"],["عَذَابًۭا","azab"],["شَدِيدًا ۖ","teruk"],["إِنَّهُمْ","Sesungguhnya [mereka]"],["سَآءَ","jahat adalah"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"5120":["(Mereka menjadikan sumpah-sumpah mereka sebagai perisai) untuk melindungi jiwa dan harta mereka (lalu mereka halangi) dengan sumpah mereka itu orang-orang mukmin (dari jalan Allah) untuk berjihad melawan mereka yang musuh dalam selimut itu, dengan cara membunuh mereka dan merampas harta benda mereka (karena itu mereka mendapat azab yang menghinakan) siksaan yang membuat mereka hina.",[["ٱتَّخَذُوٓا۟","Mereka telah mengambil"],["أَيْمَـٰنَهُمْ","sumpah mereka"],["جُنَّةًۭ","(sebagai) penutup"],["فَصَدُّوا۟","jadi mereka menghalang"],["عَن","daripada"],["سَبِيلِ","(jalan) Allah"],["ٱللَّهِ","(jalan) Allah"],["فَلَهُمْ","jadi bagi mereka"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"5121":["(Harta benda dan anak-anak mereka tiada berguna untuk menolong mereka dari Allah) dari azab-Nya (barang sedikit pun) yakni tiada berguna sama sekali. (Mereka itulah penghuni neraka, mereka kekal di dalamnya).",[["لَّن","tidak pernah"],["تُغْنِىَ","akan mendapat manfaat"],["عَنْهُمْ","mereka"],["أَمْوَٰلُهُمْ","kekayaan mereka"],["وَلَآ","dan bukan"],["أَوْلَـٰدُهُم","anak-anak mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًٔا ۚ","(dalam) apa-apa"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["أَصْحَـٰبُ","(akan menjadi) sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","akan kekal selama-lamanya"]]],"5122":["Ingatlah (hari ketika mereka dibangkitkan Allah semuanya, lalu mereka bersumpah kepada-Nya) bahwasanya mereka adalah orang-orang yang beriman (sebagaimana mereka bersumpah kepada kalian; dan mereka menyangka bahwa sesungguhnya mereka akan memperoleh sesuatu) manfaat dari sumpah mereka di akhirat itu sebagaimana sumpah mereka di dunia. (Ketahuilah, bahwa sesungguhnya merekalah orang-orang pendusta).",[["يَوْمَ","(Pada) Hari"],["يَبْعَثُهُمُ","Allah akan membangkitkan mereka"],["ٱللَّهُ","Allah akan membangkitkan mereka"],["جَمِيعًۭا","semua"],["فَيَحْلِفُونَ","maka mereka akan bersumpah"],["لَهُۥ","kepada-Nya"],["كَمَا","seperti"],["يَحْلِفُونَ","mereka bersumpah"],["لَكُمْ ۖ","kepada kamu"],["وَيَحْسَبُونَ","Dan mereka berfikir"],["أَنَّهُمْ","bahawa mereka"],["عَلَىٰ","(ada) pada"],["شَىْءٍ ۚ","sesuatu"],["أَلَآ","Tidak syak lagi"],["إِنَّهُمْ","Sesungguhnya mereka"],["هُمُ","[mereka]"],["ٱلْكَـٰذِبُونَ","(adalah) orang-orang yang berdusta"]]],"5123":["(Telah berkuasa) maksudnya telah berhasil mempengaruhi (atas mereka setan) karena ternyata mereka menaatinya (lalu menjadikan mereka lupa mengingat Allah; mereka itulah golongan setan) yakni pengikut-pengikutnya. (Ketahuilah bahwa sesungguhnya golongan setan itulah golongan yang merugi).",[["ٱسْتَحْوَذَ","Telah mengatasi"],["عَلَيْهِمُ","mereka"],["ٱلشَّيْطَـٰنُ","syaitan"],["فَأَنسَىٰهُمْ","jadi dia membuat mereka lupa"],["ذِكْرَ","(the) zikir"],["ٱللَّهِ ۚ","(milik) Allah"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["حِزْبُ","(adalah) parti"],["ٱلشَّيْطَـٰنِ ۚ","(dari) syaitan"],["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["حِزْبَ","(the) parti"],["ٱلشَّيْطَـٰنِ","(dari) syaitan"],["هُمُ","mereka"],["ٱلْخَـٰسِرُونَ","(akan menjadi) orang-orang yang rugi"]]],"5124":["(Sesungguhnya orang-orang yang menentang) melawan (Allah dan Rasul-Nya, mereka termasuk orang-orang yang sangat hina) yang dikalahkan.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُحَآدُّونَ","menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥٓ","dan Rasul-Nya"],["أُو۟لَـٰٓئِكَ","mereka"],["فِى","(akan) antara"],["ٱلْأَذَلِّينَ","yang paling dihina"]]],"5125":["(Allah telah menetapkan) di Lohmahfuz, atau Allah telah memastikan: (\"Aku dan Rasul-Ku pasti menang.\") Dalam berhujah atau berdebat atau menggunakan senjata. (Sesungguhnya Allah Maha Kuat lagi Maha Perkasa).",[["كَتَبَ","Allah dah takdirkan"],["ٱللَّهُ","Allah dah takdirkan"],["لَأَغْلِبَنَّ","Pasti, aku akan mengatasi"],["أَنَا۠","aku"],["وَرُسُلِىٓ ۚ","dan Rasul-rasulKu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["قَوِىٌّ","(adalah) Maha Kuat"],["عَزِيزٌۭ","Maha Perkasa"]]],"5126":["(Kamu tidak akan mendapati sesuatu kaum yang beriman kepada Allah dan hari akhirat, saling berkasih sayang) artinya berteman (dengan orang-orang yang menentang Allah dan Rasul-Nya sekalipun orang-orang itu) yakni orang-orang yang menentang itu (bapak-bapak mereka) yakni bapak-bapak orang-orang yang beriman (atau anak-anak mereka, atau saudara-saudara mereka, atau pun keluarga mereka) bahkan orang-orang yang beriman itu pasti memusuhi mereka dan memerangi mereka demi keimanannya, sebagaimana yang dialami oleh sebagian para sahabat. (Mereka itulah) orang-orang yang tidak mau berkasih sayang dengan orang-orang yang menentang Allah dan Rasul-Nya (yang Allah telah menanamkan) yakni meneguhkan (keimanan dalam kalbu mereka dan menguatkan mereka dengan cahaya) yakni nur (dari-Nya) dari Allah swt. (Dan dimasukkan-Nya mereka ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Allah rida terhadap mereka) karena ketaatan mereka kepada-Nya (dan mereka pun merasa puas terhadap-Nya) atas pahala. (Mereka itulah golongan Allah) artinya yang mengikuti perintah-Nya dan menjauhi larangan-Nya. (Ketahuilah, bahwa sesungguhnya golongan Allah itulah yang beruntung) yang memperoleh keberuntungan.",[["لَّا","Kamu tidak akan dapati"],["تَجِدُ","Kamu tidak akan dapati"],["قَوْمًۭا","suatu kaum"],["يُؤْمِنُونَ","yang beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","yang Terakhir"],["يُوَآدُّونَ","penyayang"],["مَنْ","(mereka) yang"],["حَآدَّ","menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَلَوْ","walaupun"],["كَانُوٓا۟","mereka adalah"],["ءَابَآءَهُمْ","bapa mereka"],["أَوْ","atau"],["أَبْنَآءَهُمْ","anak lelaki mereka"],["أَوْ","atau"],["إِخْوَٰنَهُمْ","saudara mereka"],["أَوْ","atau"],["عَشِيرَتَهُمْ ۚ","kaum kerabat mereka"],["أُو۟لَـٰٓئِكَ","Itu"],["كَتَبَ","Dia telah menetapkan"],["فِى","dalam"],["قُلُوبِهِمُ","hati mereka"],["ٱلْإِيمَـٰنَ","iman"],["وَأَيَّدَهُم","dan menyokong mereka"],["بِرُوحٍۢ","dengan semangat"],["مِّنْهُ ۖ","daripadaNya"],["وَيُدْخِلُهُمْ","Dan Dia akan mengakui mereka"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","akan kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["رَضِىَ","Allah redha"],["ٱللَّهُ","Allah redha"],["عَنْهُمْ","bersama mereka"],["وَرَضُوا۟","dan mereka redha"],["عَنْهُ ۚ","dengan Dia"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["حِزْبُ","(adalah) parti"],["ٱللَّهِ ۚ","(milik) Allah"],["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["حِزْبَ","(the) parti"],["ٱللَّهِ","(milik) Allah"],["هُمُ","mereka"],["ٱلْمُفْلِحُونَ","(adalah) orang-orang yang berjaya"]]],"5127":["(Bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi) semuanya memahasucikan-Nya. Huruf lam pada lafal lillaahi adalah zaidah; ungkapan dengan memakai lafal maa, karena lebih memprioritaskan makhluk yang tidak berakal yang jumlahnya lebih banyak (dan Dialah Yang Maha Perkasa lagi Maha Bijaksana) di dalam kerajaan-Nya dan dalam perbuatan-Nya.",[["سَبَّحَ","Memuliakan"],["لِلَّهِ","[kepada] Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۖ","bumi"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5128":["(Dialah Yang mengeluarkan orang-orang kafir di antara ahli kitab) mereka adalah Bani Nadhir yang terdiri dari orang-orang Yahudi (dari kampung mereka) dari tempat-tempat tinggal mereka di Madinah (pada saat pengusiran pertama) yaitu sewaktu mereka diusir ke negeri Syam, dan terakhir mereka diusir ke tanah Khaibar oleh Khalifah Umar semasa ia menjabat sebagai khalifah. (Kalian tidak mengira) hai orang-orang mukmin (bahwa mereka akan keluar dan mereka pun yakin, bahwa dapat mencegah mereka) lafal maani'atuhum adalah khabar dari anna (benteng-benteng mereka) menjadi fa'il dari lafal maani'atuhum; dan dengan keberadaannya maka lengkaplah pengertian khabar (dari Allah) yakni dari azab-Nya (maka Allah mendatangkan kepada mereka) hukuman dan azab-Nya (dari arah yang tidak mereka sangka-sangka) yakni dari pihak kaum mukminin yang hal ini tidak masuk ke dalam perhitungan mereka. (Dan Allah melemparkan) maksudnya menanamkan (rasa takut ke dalam hati mereka) dapat dibaca ar-ru'ba atau ar-ru'uba, artinya rasa takut mati, karena pemimpin mereka bernama Ka'b bin Asyraf telah terbunuh mati (mereka memusnahkan) dapat dibaca yukharribuuna, dan kalau dibaca yukhribuuna berarti berasal dari lafal akhraba, artinya merusak (rumah-rumah mereka) untuk mengambil barang-barang yang dianggap berharga oleh mereka berupa kayu-kayu dan lain-lainnya (dengan tangan mereka sendiri dan tangan orang-orang yang beriman. Maka ambillah hal itu untuk menjadi pelajaran, hai orang-orang yang mempunyai pandangan).",[["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَخْرَجَ","diusir"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْ","daripada"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","(dari) Kitab Suci"],["مِن","daripada"],["دِيَـٰرِهِمْ","rumah mereka"],["لِأَوَّلِ","pada (yang) pertama"],["ٱلْحَشْرِ ۚ","perhimpunan"],["مَا","Tidak"],["ظَنَنتُمْ","kamu fikir"],["أَن","bahawa"],["يَخْرُجُوا۟ ۖ","mereka akan pergi"],["وَظَنُّوٓا۟","dan mereka berfikir"],["أَنَّهُم","bahawa [mereka]"],["مَّانِعَتُهُمْ","akan membela mereka"],["حُصُونُهُم","kubu-kubu mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["فَأَتَىٰهُمُ","Tetapi datang kepada mereka"],["ٱللَّهُ","Allah"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَمْ","tidak"],["يَحْتَسِبُوا۟ ۖ","mereka jangkakan"],["وَقَذَفَ","dan Dia melemparkan"],["فِى","ke dalam"],["قُلُوبِهِمُ","hati mereka"],["ٱلرُّعْبَ ۚ","keganasan"],["يُخْرِبُونَ","mereka musnahkan"],["بُيُوتَهُم","rumah mereka"],["بِأَيْدِيهِمْ","dengan tangan mereka"],["وَأَيْدِى","dan tangan"],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"],["فَٱعْتَبِرُوا۟","Jadi ambil pengajaran"],["يَـٰٓأُو۟لِى","Wahai mereka yang dikurniakan"],["ٱلْأَبْصَـٰرِ","(dengan) wawasan"]]],"5129":["(Dan jika tidaklah karena Allah telah menetapkan) telah memastikan (pengusiran terhadap mereka) yakni dikeluarkan dari kampung halamannya (benar-benar Allah mengazab mereka di dunia) dengan dibunuh dan ditawan, sebagaimana yang telah dilakukan-Nya terhadap orang-orang Yahudi Bani Quraizhah. (Dan bagi mereka di akhirat azab neraka).",[["وَلَوْلَآ","Dan jika tidak"],["أَن","[bahawa]"],["كَتَبَ","(telah) memutuskan"],["ٱللَّهُ","Allah"],["عَلَيْهِمُ","bagi mereka"],["ٱلْجَلَآءَ","pengasingan itu"],["لَعَذَّبَهُمْ","sesungguhnya Dia (akan) mengazab mereka"],["فِى","dalam"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَهُمْ","dan untuk mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["عَذَابُ","(ialah) azab"],["ٱلنَّارِ","(dari) api"]]],"5130":["(Yang demikian itu adalah karena sesungguhnya mereka telah menentang) telah melawan (Allah dan Rasul-Nya. Barang siapa menentang Allah, maka sesungguhnya Allah sangat keras hukuman-Nya) terhadap dia.",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana [mereka]"],["شَآقُّوا۟","mereka menentang"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ ۖ","dan Rasul-Nya"],["وَمَن","Dan sesiapa"],["يُشَآقِّ","menentang"],["ٱللَّهَ","Allah"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) penalti"]]],"5131":["(Apa saja yang kalian tebang) hai orang-orang muslim (dari pohon kurma) milik orang kafir (atau yang kalian biarkan tumbuh berdiri di atas pokoknya, maka semua itu adalah dengan izin Allah) yakni Allah swt. menyerahkannya kepada kalian (dan karena Dia hendak memberikan kehinaan) dengan mengizinkan kalian menebangnya (kepada orang-orang fasik) yakni orang-orang Yahudi, karena mereka telah menentang, bahwa menebang pohon yang berbuah itu adalah pengrusakan.",[["مَا","apapun"],["قَطَعْتُم","kamu tebang"],["مِّن","daripada"],["لِّينَةٍ","(the) pokok palma"],["أَوْ","atau"],["تَرَكْتُمُوهَا","kamu tinggalkan mereka"],["قَآئِمَةً","berdiri"],["عَلَىٰٓ","pada"],["أُصُولِهَا","akar mereka"],["فَبِإِذْنِ","ia (adalah) dengan izin"],["ٱللَّهِ","(milik) Allah"],["وَلِيُخْزِىَ","dan supaya Dia menghinakan"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"5132":["(Dan apa saja harta difaikan) harta yang diberikan (oleh Allah kepada Rasul-Nya dari harta benda mereka, maka kalian tidak mengerahkan) tidak melarikan hai kaum muslimin (untuk mendapatkannya) huruf min di sini adalah huruf zaidah (seekor kuda pun dan tidak pula seekor unta pun) yang dimaksud dengan lafal rikabin adalah unta kendaraan. Makna yang dimaksud ialah bahwa untuk mendapatkan harta fai itu kalian tidak susah payah lagi (tetapi Allah yang memberikan kekuasaan kepada Rasul-Nya terhadap siapa yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu) maka tidak ada hak lagi bagi kalian dalam harta fai itu; itu khusus hanya untuk Nabi saw. dan untuk orang-orang yang akan disebutkan pada ayat selanjutnya, yaitu terdiri dari empat golongan, sesuai dengan apa yang telah ditentukan oleh Allah dalam pembagiannya. Maka bagi setiap golongan di antara mereka mendapatkan seperlimanya, dan bagi Nabi saw. sendiri adalah sisanya, artinya sama juga dengan seperlima. Nabi saw. boleh memberlakukan bagiannya itu sesuai dengan apa yang disukainya, untuk itu maka beliau memberikan sebagian daripadanya kepada orang-orang Muhajirin dan tiga orang dari kalangan sahabat Ansar karena mengingat kefakiran mereka.",[["وَمَآ","Dan apa"],["أَفَآءَ","(telah) dipulihkan"],["ٱللَّهُ","(oleh) Allah"],["عَلَىٰ","kepada"],["رَسُولِهِۦ","RasulNya"],["مِنْهُمْ","daripada mereka"],["فَمَآ","maka tidak"],["أَوْجَفْتُمْ","kamu buat ekspedisi"],["عَلَيْهِ","baginya"],["مِنْ","daripada"],["خَيْلٍۢ","kuda"],["وَلَا","dan bukan"],["رِكَابٍۢ","unta"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["يُسَلِّطُ","memberi kuasa"],["رُسُلَهُۥ","(kepada) Rasul-rasulNya"],["عَلَىٰ","atas"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"5133":["(Apa saja harta rampasan atau fai yang diberikan Allah kepada Rasul-Nya yang berasal dari penduduk kota-kota) seperti tanah Shafra, lembah Al-Qura dan tanah Yanbu' (maka adalah untuk Allah) Dia memerintahkannya sesuai dengan apa yang dikehendaki-Nya (untuk Rasul, orang-orang yang mempunyai) atau memiliki (hubungan kekerabatan) yaitu kaum kerabat Nabi dari kalangan Bani Hasyim dan Bani Mutthalib (anak-anak yatim) yaitu anak-anak kaum muslimin yang bapak-bapak mereka telah meninggal dunia sedangkan mereka dalam keadaan fakir (orang-orang miskin) yaitu orang-orang muslim yang serba kekurangan (dan orang-orang yang dalam perjalanan) yakni orang-orang muslim yang mengadakan perjalanan lalu terhenti di tengah jalan karena kehabisan bekal. Yakni harta fai itu adalah hak Nabi saw. beserta empat golongan orang-orang tadi, sesuai dengan apa yang telah ditentukan oleh Allah swt. dalam pembagiannya, yaitu bagi masing-masing golongan yang empat tadi seperlimanya dan sisanya untuk Nabi saw. (supaya janganlah) lafal kay di sini bermakna lam, dan sesudah kay diperkirakan adanya lafal an (harta fai itu) yakni harta rampasan itu, dengan adanya pembagian ini (hanya beredar) atau berpindah-pindah (di antara orang-orang kaya saja di antara kalian. Apa yang telah diberikan kepada kalian) yakni bagian yang telah diberikan kepada kalian (oleh Rasul) berupa bagian harta fa-i dan harta-harta lainnya (maka terimalah dia. Dan apa yang dilarangnya bagi kalian maka tinggalkanlah; dan bertakwalah kepada Allah. Sesungguhnya Allah sangat keras hukuman-Nya).",[["مَّآ","Apa"],["أَفَآءَ","(telah) dipulihkan"],["ٱللَّهُ","(oleh) Allah"],["عَلَىٰ","kepada"],["رَسُولِهِۦ","RasulNya"],["مِنْ","daripada"],["أَهْلِ","kaum"],["ٱلْقُرَىٰ","(dari) bandar-bandar"],["فَلِلَّهِ","(itu adalah) untuk Allah"],["وَلِلرَّسُولِ","dan Rasul-Nya"],["وَلِذِى","dan untuk mereka"],["ٱلْقُرْبَىٰ","(daripada) kaum kerabat"],["وَٱلْيَتَـٰمَىٰ","dan anak-anak yatim"],["وَٱلْمَسَـٰكِينِ","dan yang memerlukan"],["وَٱبْنِ","dan"],["ٱلسَّبِيلِ","pengembara"],["كَىْ","bahawa"],["لَا","tidak"],["يَكُونَ","ia menjadi"],["دُولَةًۢ","peredaran (kekal)."],["بَيْنَ","antara"],["ٱلْأَغْنِيَآءِ","orang kaya"],["مِنكُمْ ۚ","antara kamu"],["وَمَآ","Dan apa sahaja"],["ءَاتَىٰكُمُ","memberi kamu"],["ٱلرَّسُولُ","Rasul"],["فَخُذُوهُ","ambillah"],["وَمَا","dan apa sahaja"],["نَهَىٰكُمْ","dia melarang kamu"],["عَنْهُ","daripadanya"],["فَٱنتَهُوا۟ ۚ","menahan diri"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ ۖ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["شَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) penalti"]]],"5134":["(Terhadap orang-orang fakir) bertaalluq kepada lafal yang tidak disebutkan, lengkapnya: Takjublah kalian terhadap orang-orang fakir (yang berhijrah, yang diusir dari kampung halaman dan dari harta benda mereka karena mencari karunia dari Allah dan keridaan-Nya dan mereka menolong agama, Allah dan Rasul-Nya. Mereka itulah orang-orang yang benar) dalam keimanannya.",[["لِلْفُقَرَآءِ","Untuk orang miskin"],["ٱلْمُهَـٰجِرِينَ","pendatang"],["ٱلَّذِينَ","orang yang"],["أُخْرِجُوا۟","telah dibuang"],["مِن","daripada"],["دِيَـٰرِهِمْ","rumah mereka"],["وَأَمْوَٰلِهِمْ","dan harta benda mereka"],["يَبْتَغُونَ","mencari"],["فَضْلًۭا","kurniaan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَرِضْوَٰنًۭا","dan kesenangan"],["وَيَنصُرُونَ","dan membantu"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥٓ ۚ","dan Rasul-Nya"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","mereka"],["ٱلصَّـٰدِقُونَ","(adalah) orang-orang yang benar"]]],"5135":["(Dan orang-orang yang telah menempati kota) Madinah (dan telah beriman) yang dimaksud adalah sahabat-sahabat Anshar (sebelum kedatangan mereka, Muhajirin, mereka mencintai orang-orang yang berhijrah kepada mereka. Dan mereka tiada menaruh keinginan dalam hati mereka) artinya mereka tidak iri hati (terhadap apa-apa yang diberikan kepada mereka) yakni apa yang telah diberikan oleh Nabi saw. kepada mereka berupa harta rampasan dari Bani Nadhir, yang memang harta itu khusus buat kaum Muhajirin (dan mereka mengutamakan, orang-orang Muhajirin, atas diri mereka sendiri sekalipun mereka dalam kesusahan) yakni mereka memerlukan apa yang mereka relakan kepada orang-orang Muhajirin. (Dan siapa yang dipelihara dari kekikiran dirinya) dari ketamakannya terhadap harta benda (mereka itulah orang-orang yang beruntung).",[["وَٱلَّذِينَ","Dan orang yang"],["تَبَوَّءُو","diselesaikan"],["ٱلدَّارَ","(dalam) rumah"],["وَٱلْإِيمَـٰنَ","dan (diterima) iman"],["مِن","daripada"],["قَبْلِهِمْ","sebelum mereka"],["يُحِبُّونَ","cinta"],["مَنْ","(mereka) yang"],["هَاجَرَ","berhijrah"],["إِلَيْهِمْ","kepada mereka"],["وَلَا","dan bukan"],["يَجِدُونَ","mereka dapati"],["فِى","dalam"],["صُدُورِهِمْ","buah dada mereka"],["حَاجَةًۭ","sebarang kehendak"],["مِّمَّآ","tentang apa"],["أُوتُوا۟","mereka diberi"],["وَيُؤْثِرُونَ","tetapi lebih suka"],["عَلَىٰٓ","atas"],["أَنفُسِهِمْ","diri mereka"],["وَلَوْ","walaupun"],["كَانَ","adalah"],["بِهِمْ","bersama mereka"],["خَصَاصَةٌۭ ۚ","kemiskinan"],["وَمَن","Dan sesiapa"],["يُوقَ","disimpan"],["شُحَّ","(dari) kedekut"],["نَفْسِهِۦ","(dari) jiwanya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْمُفْلِحُونَ","(adalah) orang-orang yang berjaya"]]],"5136":["(Dan orang-orang yang datang sesudah mereka) yakni sesudah kaum Muhajirin dan kaum Ansar hingga hari kiamat nanti (mereka berdoa, \"Ya Rabb kami! Beri ampunlah kami dan saudara-saudara kami yang telah beriman lebih dahulu dari kami, dan janganlah Engkau membiarkan kedengkian dalam hati kami) yakni rasa dengki (terhadap orang-orang yang beriman; Ya Rabb kami, sesungguhnya Engkau Maha Penyantun lagi Maha Penyayang.\")",[["وَٱلَّذِينَ","Dan orang yang"],["جَآءُو","datang"],["مِنۢ","daripada"],["بَعْدِهِمْ","selepas mereka"],["يَقُولُونَ","mereka berkata"],["رَبَّنَا","Wahai Tuhan kami"],["ٱغْفِرْ","maafkan"],["لَنَا","kami"],["وَلِإِخْوَٰنِنَا","dan saudara kita"],["ٱلَّذِينَ","yang"],["سَبَقُونَا","mendahului kami"],["بِٱلْإِيمَـٰنِ","dalam iman"],["وَلَا","dan jangan"],["تَجْعَلْ","meletakkan"],["فِى","dalam"],["قُلُوبِنَا","hati kita"],["غِلًّۭا","sebarang dendam"],["لِّلَّذِينَ","terhadap mereka yang"],["ءَامَنُوا۟","beriman"],["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّكَ","sesungguhnya Engkau"],["رَءُوفٌۭ","(adalah) Penuh Kebaikan"],["رَّحِيمٌ","Maha Mengasihani"]]],"5137":["(Apakah kamu tiada memperhatikan) tiada melihat (orang-orang yang munafik yang berkata kepada saudara-saudara mereka yang kafir di antara ahli kitab) yaitu kepada Bani Nadhir dan saudara-saudara mereka yang kafir: (\"Sesungguhnya jika) huruf lam di sini menunjukkan makna qasam dan demikian pula pada tempat-tempat lainnya yang semuanya ada di empat tempat (kalian diusir) dari Madinah (niscaya kami pun akan keluar bersama kalian, dan kami tidak akan patuh untuk menghinakan kalian) yakni untuk menjadikan kalian terhina (kepada siapa pun selama-lamanya, dan jika kalian diperangi) dari lafal wa in terbuang huruf lam yang menunjukkan makna permulaan (pasti kami akan membantu kalian.\" Dan Allah menyaksikan, bahwa sesungguhnya mereka benar-benar pendusta).",[["۞ أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["إِلَى","[ke]"],["ٱلَّذِينَ","orang yang"],["نَافَقُوا۟","(adalah) orang-orang munafik"],["يَقُولُونَ","berkata"],["لِإِخْوَٰنِهِمُ","kepada saudara-saudara mereka"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْ","antara"],["أَهْلِ","Rakyat"],["ٱلْكِتَـٰبِ","(dari) Kitab Suci"],["لَئِنْ","Jika"],["أُخْرِجْتُمْ","kamu dibuang kerja"],["لَنَخْرُجَنَّ","pasti kita akan pergi"],["مَعَكُمْ","bersama kamu"],["وَلَا","dan bukan"],["نُطِيعُ","kami akan patuh"],["فِيكُمْ","berkenaan kamu"],["أَحَدًا","sesiapa sahaja"],["أَبَدًۭا","pernah"],["وَإِن","dan jika"],["قُوتِلْتُمْ","kamu diperangi"],["لَنَنصُرَنَّكُمْ","pasti kami akan membantu kamu"],["وَٱللَّهُ","Dan Allah"],["يَشْهَدُ","menjadi saksi"],["إِنَّهُمْ","bahawa mereka"],["لَكَـٰذِبُونَ","(adalah) sesungguhnya pendusta"]]],"5138":["(Sesungguhnya jika mereka diusir, orang-orang munafik itu tiada akan keluar bersama mereka, dan sesungguhnya jika mereka diperangi, niscaya mereka tidak akan menolongnya; sesungguhnya jika mereka menolongnya) artinya mereka datang untuk menolong dan membantunya (niscaya mereka akan berpaling ke belakang) jawab qasam yang keberadaannya diperkirakan sudah memberikan pengertian yang cukup, tanpa harus menyebut jawab syarat pada kelima tempat tadi (kemudian mereka tidak akan mendapat pertolongan) yang dimaksud adalah orang-orang Yahudi.",[["لَئِنْ","Jika"],["أُخْرِجُوا۟","mereka dihalau"],["لَا","tidak"],["يَخْرُجُونَ","mereka akan pergi"],["مَعَهُمْ","bersama mereka"],["وَلَئِن","dan jika"],["قُوتِلُوا۟","mereka diperangi"],["لَا","tidak"],["يَنصُرُونَهُمْ","mereka akan membantu mereka"],["وَلَئِن","Dan jika"],["نَّصَرُوهُمْ","mereka membantu mereka"],["لَيُوَلُّنَّ","nescaya mereka akan berpaling"],["ٱلْأَدْبَـٰرَ","(mereka) belakang"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُنصَرُونَ","mereka akan dibantu"]]],"5139":["(Sesungguhnya kalian lebih ditakuti) lebih disegani (dalam hati mereka) dalam hati orang-orang munafik itu (daripada Allah) karena siksaan-Nya yang ditangguhkan. (Yang demikian itu karena mereka adalah kaum yang tiada mengerti.",[["لَأَنتُمْ","Pasti kamu"],["أَشَدُّ","(adalah) lebih sengit"],["رَهْبَةًۭ","(dalam) ketakutan"],["فِى","dalam"],["صُدُورِهِم","buah dada mereka"],["مِّنَ","daripada"],["ٱللَّهِ ۚ","Allah"],["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["لَّا","(yang melakukannya) tidak"],["يَفْقَهُونَ","faham"]]],"5140":["(Mereka tidak akan memerangi kalian) yakni orang-orang Yahudi itu (dalam keadaan bersatu padu) maksudnya, secara serentak (kecuali dalam kampung-kampung yang berbenteng atau di balik tembok) yang tinggi. Menurut suatu qiraat lafal judurin dibaca jidaarin. (Permusuhan) peperangan (di antara sesama mereka sangat hebat. Kalian kira mereka itu bersatu sedangkan hati mereka berpecah belah) berbeda-beda, bertentangan dengan apa yang diduga. (Yang demikian itu karena sesungguhnya mereka adalah kaum yang tiada mengerti).",[["لَا","Tidak"],["يُقَـٰتِلُونَكُمْ","adakah mereka akan memerangi kamu"],["جَمِيعًا","semua"],["إِلَّا","kecuali"],["فِى","dalam"],["قُرًۭى","bandar-bandar"],["مُّحَصَّنَةٍ","diperkukuhkan"],["أَوْ","atau"],["مِن","daripada"],["وَرَآءِ","belakang"],["جُدُرٍۭ ۚ","dinding"],["بَأْسُهُم","Keganasan mereka"],["بَيْنَهُمْ","sesama mereka"],["شَدِيدٌۭ ۚ","(adalah) teruk"],["تَحْسَبُهُمْ","Kamu fikir mereka"],["جَمِيعًۭا","(adalah) bersatu"],["وَقُلُوبُهُمْ","tetapi hati mereka"],["شَتَّىٰ ۚ","(adalah) dibahagikan"],["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana mereka"],["قَوْمٌۭ","(adalah) suatu kaum"],["لَّا","tidak"],["يَعْقِلُونَ","mereka beralasan"]]],"5141":["Perumpamaan mereka dalam hal tidak mau beriman (seperti orang-orang yang belum lama sebelum mereka) yakni sebagaimana orang-orang musyrik yang terlibat dalam perang Badar (yang telah merasai akibat buruk dari perbuatan mereka) sebagai hukuman-Nya di dunia, yaitu mereka mati terbunuh dan hukuman-hukuman yang lainnya yang mereka rasakan (dan bagi mereka azab yang pedih) siksaan yang menyakitkan kelak di akhirat.",[["كَمَثَلِ","Seperti (contohnya)."],["ٱلَّذِينَ","orang"],["مِن","daripada"],["قَبْلِهِمْ","sebelum mereka"],["قَرِيبًۭا ۖ","sebentar lagi"],["ذَاقُوا۟","mereka rasa"],["وَبَالَ","(akibat) jahat"],["أَمْرِهِمْ","(dari) urusan mereka"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"5142":["Dan juga perumpamaan mereka dalam hal mendengar dari orang-orang munafik, tetapi orang-orang munafik itu tidak mau mengikuti jejak mereka sesudahnya (seperti halnya setan; ia berkata kepada manusia, \"Kafirlah kamu,\" maka tatkala manusia itu telah kafir, ia berkata, \"Sesungguhnya aku berlepas diri dari kamu karena sesungguhnya aku takut kepada Allah, Rabb semesta alam.\") Padahal ia dusta dan hanya ria belaka.",[["كَمَثَلِ","Seperti (contohnya)."],["ٱلشَّيْطَـٰنِ","(dari) syaitan"],["إِذْ","apabila"],["قَالَ","katanya"],["لِلْإِنسَـٰنِ","kepada manusia"],["ٱكْفُرْ","tak beriman"],["فَلَمَّا","Tetapi apabila"],["كَفَرَ","dia tak beriman"],["قَالَ","katanya"],["إِنِّى","Memang aku"],["بَرِىٓءٌۭ","dipisahkan"],["مِّنكَ","daripada kamu"],["إِنِّىٓ","Sesungguhnya, [aku]"],["أَخَافُ","aku takut"],["ٱللَّهَ","Allah"],["رَبَّ","(yang) Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"5143":["(Maka adalah sesudah keduanya) yakni orang yang sesat dan orang yang disesatkan. Menurut suatu qiraat lafal 'aaqibatahumaa dibaca 'aaqibatuhumaa dengan memakai harakat damah di atas huruf ta, hal ini berarti sebagai isim dari lafal kaana (bahwa sesungguhnya keduanya masuk ke dalam neraka, mereka kekal di dalamnya. Demikianlah balasan orang-orang yang lalim) orang-orang yang kafir.",[["فَكَانَ","Begitu juga"],["عَـٰقِبَتَهُمَآ","(akhir) mereka berdua"],["أَنَّهُمَا","bahawa mereka"],["فِى","(akan) masuk"],["ٱلنَّارِ","neraka"],["خَـٰلِدَيْنِ","kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["وَذَٰلِكَ","Dan bahawa"],["جَزَٰٓؤُا۟","(ialah) balasan"],["ٱلظَّـٰلِمِينَ","(dari) orang-orang yang zalim"]]],"5144":["(Hai orang-orang yang beriman! Bertakwalah kepada Allah dan hendaklah setiap diri memperhatikan apa yang telah diperbuatnya untuk hari esok) yakni untuk menghadapi hari kiamat (dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kalian kerjakan).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","kamu (siapa)"],["ءَامَنُوا۟","beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["وَلْتَنظُرْ","dan mari lihat"],["نَفْسٌۭ","setiap jiwa"],["مَّا","apa"],["قَدَّمَتْ","ia telah dihantar"],["لِغَدٍۢ ۖ","untuk esok"],["وَٱتَّقُوا۟","dan ketakutan"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"5145":["(Dan janganlah kalian seperti orang-orang yang lupa kepada Allah) maksudnya tidak mau taat kepada-Nya (lalu Allah menjadikan mereka lupa kepada diri mereka sendiri) untuk melakukan perbuatan ketaatan dan perbuatan baik. (Mereka itulah orang-orang yang fasik).",[["وَلَا","Dan jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّذِينَ","seperti mereka yang"],["نَسُوا۟","terlupa"],["ٱللَّهَ","Allah"],["فَأَنسَىٰهُمْ","maka Dia menjadikan mereka lupa"],["أَنفُسَهُمْ ۚ","diri mereka"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","[mereka]"],["ٱلْفَـٰسِقُونَ","(adalah) orang-orang yang durhaka"]]],"5146":["(Tidak sama penghuni-penghuni neraka dengan penghuni-penghuni surga; penghuni-penghuni surga itulah orang-orang yang beruntung).",[["لَا","Tidak"],["يَسْتَوِىٓ","sama rata"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ","(dari) api"],["وَأَصْحَـٰبُ","dan (para) sahabat"],["ٱلْجَنَّةِ ۚ","(dari) Syurga"],["أَصْحَـٰبُ","(Para) sahabat"],["ٱلْجَنَّةِ","(dari) Syurga"],["هُمُ","mereka"],["ٱلْفَآئِزُونَ","(adalah) orang yang berjaya"]]],"5147":["(Kalau sekiranya Kami menurunkan Alquran ini kepada sebuah gunung) lalu dijadikan-Nya pada gunung tersebut akal sebagaimana manusia (pasti kamu akan melihatnya tunduk terpecah belah) terbelah-belah (disebabkan takut kepada Allah. Dan perumpamaan-perumpamaan itu) yang telah disebutkan di atas tadi (Kami buat untuk manusia supaya mereka berpikir) yang karenanya lalu mereka beriman.",[["لَوْ","Jika"],["أَنزَلْنَا","Kami (telah) menurunkan"],["هَـٰذَا","ini"],["ٱلْقُرْءَانَ","Quran"],["عَلَىٰ","pada"],["جَبَلٍۢ","sebuah gunung"],["لَّرَأَيْتَهُۥ","nescaya kamu (akan) melihatnya"],["خَـٰشِعًۭا","merendah diri"],["مُّتَصَدِّعًۭا","pecah belah"],["مِّنْ","daripada"],["خَشْيَةِ","(yang) takut"],["ٱللَّهِ ۚ","(milik) Allah"],["وَتِلْكَ","Dan ini"],["ٱلْأَمْثَـٰلُ","contoh"],["نَضْرِبُهَا","Kami membentangkannya"],["لِلنَّاسِ","kepada rakyat"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَفَكَّرُونَ","fikirkan"]]],"5148":["(Dialah Allah Yang tiada Tuhan selain Dia, Yang Mengetahui yang gaib dan yang nyata. Dialah Yang Maha Pemurah lagi Maha Penyayang).",[["هُوَ","Dia"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Esa"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ ۖ","Dia"],["عَـٰلِمُ","(yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ ۖ","dan yang disaksikan"],["هُوَ","Dia"],["ٱلرَّحْمَـٰنُ","(adalah) Yang Maha Pemurah"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"5149":["(Dialah Allah yang tiada Tuhan selain Dia, Raja Yang Maha Suci) dari semua apa yang tidak layak bagi keagungan dan kebesaran-Nya (Yang Maha Selamat) artinya Yang Bebas dari segala sifat-sifat kekurangan (Yang Maha Mengamankan) para rasul-rasul-Nya dengan menciptakan mukjizat bagi mereka (Yang Maha Memelihara) berasal dari lafal haimana-yuhaiminu, dikatakan demikian apabila seseorang selalu mengawasi sesuatu. Makna yang dimaksud ialah, Dia Maha Menyaksikan amal perbuatan hamba-hamba-Nya (Yang Maha Perkasa) yakni Yang Maha Kuat (Yang Maha Kuasa) untuk memaksa makhluk-Nya supaya menuruti apa yang dikehendaki-Nya (Yang Maha Agung) dari semua sifat yang tidak layak bagi keagungan-Nya. (Maha Suci Allah) Dia memahasucikan Zat-Nya sendiri melalui ayat ini (dari apa yang mereka persekutukan) dengan-Nya.",[["هُوَ","Dia"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Esa"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ","Dia"],["ٱلْمَلِكُ","Yang Berdaulat"],["ٱلْقُدُّوسُ","Yang Maha Suci"],["ٱلسَّلَـٰمُ","Pemberi Damai"],["ٱلْمُؤْمِنُ","Pemberi Keselamatan"],["ٱلْمُهَيْمِنُ","sang Penjaga"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْجَبَّارُ","yang tak tertahan"],["ٱلْمُتَكَبِّرُ ۚ","Yang Maha Agung"],["سُبْحَـٰنَ","Kemuliaan (untuk)"],["ٱللَّهِ","Allah"],["عَمَّا","daripada apa"],["يُشْرِكُونَ","mereka mempersekutukan (dengan Dia)"]]],"5150":["(Dialah Allah Yang Menciptakan, Yang Mengadakan) makhluk-Nya dari tiada (Yang membentuk rupa, hanya kepunyaan-Nyalah asma-asma yang paling baik) yang berjumlah sembilan puluh sembilan, sebagaimana yang telah disebutkan dalam hadis. Lafal al-husna adalah bentuk muannats dari lafal al-ahsan. (Bertasbih kepada-Nya apa yang ada di langit dan di bumi. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana) penafsirannya sebagaimana yang telah lalu.",[["هُوَ","Dia"],["ٱللَّهُ","(ialah) Allah"],["ٱلْخَـٰلِقُ","Sang Pencipta"],["ٱلْبَارِئُ","Pencipta"],["ٱلْمُصَوِّرُ ۖ","si Fashioner"],["لَهُ","Untuk Dia"],["ٱلْأَسْمَآءُ","(adalah) nama-nama"],["ٱلْحُسْنَىٰ ۚ","yang cantik"],["يُسَبِّحُ","Memuliakan"],["لَهُۥ","Dia"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5151":["(Hai orang-orang yang beriman, janganlah kalian mengambil musuh-Ku dan musuh kalian) yakni orang-orang kafir Mekah (menjadi teman-teman setia yang kalian sampaikan) kalian beritakan (kepada mereka) tujuan Nabi saw. yang akan memerangi mereka; Nabi memerintahkan kepada kalian supaya merahasiakannya yaitu sewaktu perang Hunain (karena rasa kasih sayang) di antara kalian dan mereka. Sehubungan dengan peristiwa ini Hathib bin Abu Balta'ah mengirimkan sepucuk surat kepada orang-orang musyrik, karena Hathib mempunyai beberapa orang anak dan sanak famili yang musyrik. Akan tetapi Nabi saw. dapat mengambil surah itu dari tangan orang yang diutus olehnya, berkat pemberitahuan dari Allah kepada Nabi saw. melalui wahyu-Nya. Lalu alasan dan permintaan maaf Hathib diterima oleh Nabi saw. (padahal sesungguhnya mereka telah ingkar kepada kebenaran yang datang kepada kalian) yakni agama Islam dan Alquran (mereka mengusir Rasul dan mengusir kalian) dari Mekah setelah terlebih dahulu mereka mengganggu kalian supaya kalian keluar dari Mekah (karena kalian beriman) disebabkan kalian beriman (kepada Allah, Rabb kalian. Jika kalian benar-benar keluar untuk berjihad) untuk melakukan jihad (pada jalan-Ku dan mencari keridaan-Ku) maka janganlah kalian mengambil mereka sebagai teman-teman setia. Jawab syarat ini disimpulkan dari pengertian ayat yang selanjutnya, yaitu: (Kalian memberitahukan secara rahasia kepada mereka, karena rasa kasih sayang. Aku lebih mengetahui apa yang kalian sembunyikan dan apa yang kalian nyatakan. Dan barang siapa di antara kalian yang melakukannya) yaitu memberitahukan berita-berita Nabi saw. kepada orang-orang musyrik secara rahasia (maka sesungguhnya dia telah tersesat dari jalan yang lurus) artinya menyimpang dari jalan hidayah. Lafal as-sawaa menurut pengertian asalnya berarti tengah-tengah.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَتَّخِذُوا۟","ambil"],["عَدُوِّى","musuh aku"],["وَعَدُوَّكُمْ","dan musuhmu"],["أَوْلِيَآءَ","(sebagai) sekutu"],["تُلْقُونَ","persembahan"],["إِلَيْهِم","mereka"],["بِٱلْمَوَدَّةِ","cinta"],["وَقَدْ","sementara"],["كَفَرُوا۟","mereka telah kufur"],["بِمَا","pada apa"],["جَآءَكُم","datang kepada kamu"],["مِّنَ","daripada"],["ٱلْحَقِّ","kebenaran"],["يُخْرِجُونَ","memandu keluar"],["ٱلرَّسُولَ","Rasul"],["وَإِيَّاكُمْ ۙ","dan diri kamu sendiri"],["أَن","kerana"],["تُؤْمِنُوا۟","kamu beriman"],["بِٱللَّهِ","kepada Allah"],["رَبِّكُمْ","Tuhanmu"],["إِن","Jika"],["كُنتُمْ","kamu"],["خَرَجْتُمْ","keluar"],["جِهَـٰدًۭا","(untuk) berusaha"],["فِى","dalam"],["سَبِيلِى","cara aku"],["وَٱبْتِغَآءَ","dan (untuk) mencari"],["مَرْضَاتِى ۚ","Keseronokan Aku"],["تُسِرُّونَ","Kamu curhat"],["إِلَيْهِم","kepada mereka"],["بِٱلْمَوَدَّةِ","cinta"],["وَأَنَا۠","tetapi Aku"],["أَعْلَمُ","paling mengetahui"],["بِمَآ","tentang apa"],["أَخْفَيْتُمْ","kamu sembunyikan"],["وَمَآ","dan apa"],["أَعْلَنتُمْ ۚ","kamu isytihar"],["وَمَن","Dan sesiapa"],["يَفْعَلْهُ","melakukannya"],["مِنكُمْ","antara kamu"],["فَقَدْ","maka sudah tentu"],["ضَلَّ","dia telah sesat"],["سَوَآءَ","(dari) lurus"],["ٱلسَّبِيلِ","laluan"]]],"5152":["(Jika mereka menangkap kalian) yakni berhasil menahan kalian (niscaya mereka bertindak sebagai musuh bagi kalian dan melepaskan tangan mereka kepada kalian) maksudnya membunuh dan memukuli kalian (dan lisan mereka mengeluarkan kata-kata yang kotor) yakni mencaci maki kalian (dan mereka ingin) mengharapkan (supaya kalian kafir kembali).",[["إِن","Jika"],["يَثْقَفُوكُمْ","mereka mendapat penguasaan ke atas kamu"],["يَكُونُوا۟","mereka akan menjadi"],["لَكُمْ","kepada kamu"],["أَعْدَآءًۭ","musuh"],["وَيَبْسُطُوٓا۟","dan memanjangkan"],["إِلَيْكُمْ","terhadap kamu"],["أَيْدِيَهُمْ","tangan mereka"],["وَأَلْسِنَتَهُم","dan lidah mereka"],["بِٱلسُّوٓءِ","dengan kejahatan"],["وَوَدُّوا۟","dan mereka berkeinginan"],["لَوْ","bahawa"],["تَكْفُرُونَ","kamu akan tidak beriman"]]],"5153":["(Tidak akan bermanfaat bagi kalian karib kerabat kalian) famili-famili kalian (dan anak-anak kalian) yang musyrik, karena kalian memberitahukan berita-berita Nabi secara rahasia kepada mereka; mereka semuanya sekali-kali tiada bermanfaat bagi diri kalian untuk menolak azab di hari akhirat (pada hari kiamat Dia akan memisahkan) dapat dibaca yafshilu dan yufshalu (antara kalian) dan antara mereka; karena kalian berada di dalam surga, sedangkan mereka bersama-sama dengan orang-orang kafir di dalam neraka. (Dan Allah Maha Melihat apa yang kalian kerjakan).",[["لَن","tidak pernah"],["تَنفَعَكُمْ","akan memberi manfaat kepada kamu"],["أَرْحَامُكُمْ","saudara mara kamu"],["وَلَآ","dan bukan"],["أَوْلَـٰدُكُمْ ۚ","anak-anak kamu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["يَفْصِلُ","Dia akan menilai"],["بَيْنَكُمْ ۚ","antara kamu"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"5154":["(Sesungguhnya telah ada suri teladan bagi kalian) lafal uswatun dapat pula dibaca iswatun, artinya teladan atau panutan (yang baik pada Ibrahim) yakni pada diri Nabi Ibrahim, baik perkataan maupun perbuatannya (dan pada orang-orang yang bersama dia) dari kalangan orang-orang yang beriman (ketika mereka berkata kepada kaum mereka, \"Sesungguhnya kami berlepas diri) lafal bura-aa-u adalah bentuk jamak dari lafal barii'un, wazannya sama dengan lafal zharifun yang jamaknya zhurafaa'u (dari kalian apa yang kalian sembah selain Allah, kami ingkar kepada kekafiran kalian) kami membenci kekafiran kalian (dan telah nyata antara kami dan kalian permusuhan dan kebencian buat selama-lamanya) lafal wal baghdhaa'u abadan dapat dibaca secara tahqiq dan dapat pula dibaca secara tashil, yakni mengganti huruf hamzah yang kedua menjadi wau (sampai kalian beriman kepada Allah semata.\" Kecuali perkataan Ibrahim kepada bapaknya, \"Sesungguhnya aku akan memohonkan ampunan bagi kamu) perkataan ini merupakan perkataan yang dikecualikan daripada pengertian suri teladan tadi. Maka sekali-kali kalian tidak boleh mengucapkan kata penyesalan seperti itu, seumpamanya kalian memohonkan ampunan buat orang-orang kafir. Dan juga perkataan Nabi Ibrahim berikut ini (dan aku tiada dapat melindungimu dari Allah) dari siksaan dan pahala-Nya (barang sedikit pun.\") Nabi Ibrahim mengungkapkan kata-kata ini sebagai kiasan, bahwasanya dia tidak memiliki buatnya selain dari memohonkan ampun. Perkataan ini pun termasuk di antara hal yang dikecualikan untuk tidak boleh diikuti, karena sekalipun pengertian lahiriahnya sebagai ungkapan penyesalan, akan tetapi maksudnya berkaitan dengan pengertian kalimat yang pertama. Pengertian lahiriah kalimat yang kedua ini sama dengan pengertian yang terkandung di dalam firman Allah swt., \" Katakanlah! 'Maka siapakah gerangan yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki kemudaratan bagi kamu.'\" (Q.S. Al-Fath 11) Permohonan ampun Nabi Ibrahim buat bapaknya ini sebelum jelas bagi Nabi Ibrahim, bahwa bapaknya itu adalah benar-benar musuh Allah, sebagaimana yang telah dijelaskan di dalam surah Al-Bara'ah atau surah At-Taubah. (\"Ya Rabb kami, hanya kepada Engkaulah kami bertawakal dan hanya kepada Engkaulah kami bertobat dan hanya kepada Engkaulah kami kembali.\") Kalimat ini termasuk doa yang selalu diucapkan oleh Al-Khalil atau Nabi Ibrahim dan orang-orang beriman yang bersamanya; yakni, mereka mengucapkan kata-kata tersebut.",[["قَدْ","Sesungguhnya"],["كَانَتْ","(ada) ada"],["لَكُمْ","bagi kamu"],["أُسْوَةٌ","satu contoh"],["حَسَنَةٌۭ","kebaikan"],["فِىٓ","dalam"],["إِبْرَٰهِيمَ","Ibrahim"],["وَٱلَّذِينَ","dan mereka"],["مَعَهُۥٓ","dengan dia"],["إِذْ","apabila"],["قَالُوا۟","mereka berkata"],["لِقَوْمِهِمْ","kepada kaum mereka"],["إِنَّا","Sesungguhnya kami"],["بُرَءَٰٓؤُا۟","(adalah) dipisahkan"],["مِنكُمْ","daripada kamu"],["وَمِمَّا","dan dari apa"],["تَعْبُدُونَ","kamu menyembah"],["مِن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["كَفَرْنَا","Kami telah menafikan"],["بِكُمْ","kamu"],["وَبَدَا","dan telah muncul"],["بَيْنَنَا","antara kita"],["وَبَيْنَكُمُ","dan antara kamu"],["ٱلْعَدَٰوَةُ","permusuhan"],["وَٱلْبَغْضَآءُ","dan kebencian"],["أَبَدًا","selama-lamanya"],["حَتَّىٰ","sehingga"],["تُؤْمِنُوا۟","kamu beriman"],["بِٱللَّهِ","kepada Allah"],["وَحْدَهُۥٓ","bersendirian"],["إِلَّا","Kecuali"],["قَوْلَ","(yang) berkata"],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["لِأَبِيهِ","kepada bapanya"],["لَأَسْتَغْفِرَنَّ","Sesungguhnya aku memohon ampun"],["لَكَ","bagi kamu"],["وَمَآ","tetapi tidak"],["أَمْلِكُ","Aku ada kuasa"],["لَكَ","bagi kamu"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["مِن","daripada"],["شَىْءٍۢ ۖ","sesuatu"],["رَّبَّنَا","Wahai Tuhan kami"],["عَلَيْكَ","atas Engkau"],["تَوَكَّلْنَا","kami meletakkan kepercayaan kami"],["وَإِلَيْكَ","dan kepada-Mu"],["أَنَبْنَا","kita pusing"],["وَإِلَيْكَ","dan kepada-Mu"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"5155":["(\"Ya Rabb kami, janganlah Engkau jadikan kami sasaran fitnah bagi orang-orang kafir) maksudnya janganlah Engkau menjadikan mereka menang atas kami, sehingga nanti mereka menduga, bahwa mereka berada dalam jalan yang benar, lalu karena itu mereka terfitnah, yakni akal mereka ditujukan untuk mempengaruhi kami. (Dan ampunilah kami Ya Rabb kami. Sesungguhnya Engkau, Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.\") Maha Perkasa di dalam kerajaan-Mu lagi Maha Bijaksana perbuatan-Mu.",[["رَبَّنَا","Wahai Tuhan kami"],["لَا","jangan"],["تَجْعَلْنَا","buat kita"],["فِتْنَةًۭ","perbicaraan"],["لِّلَّذِينَ","bagi mereka yang"],["كَفَرُوا۟","kufur"],["وَٱغْفِرْ","dan memaafkan"],["لَنَا","kami"],["رَبَّنَآ ۖ","Tuhan kami"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","[Kamu]"],["ٱلْعَزِيزُ","(adalah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5156":["(Sesungguhnya telah ada bagi kalian) hai umat Muhammad, menjadi jawab qasam yang keberadaannya diperkirakan (teladan yang baik pada mereka itu, yaitu bagi orang yang mengharap pahala Allah dan hari akhirat) yakni bagi orang yang takut kepada keduanya; atau bagi orang yang menduga bahwa dirinya akan mendapat pahala dan selamat dari siksa. (Dan barang siapa yang berpaling) seumpamanya dia mengambil orang-orang kafir sebagai teman setia (maka sesungguhnya Allah, Dialah Yang Maha Kaya) yakni tidak membutuhkan makhluk-Nya (lagi Maha terpuji) di kalangan orang-orang yang taat kepada-Nya.",[["لَقَدْ","Sungguh"],["كَانَ","(ada) ada"],["لَكُمْ","bagi kamu"],["فِيهِمْ","dalam diri mereka"],["أُسْوَةٌ","satu contoh"],["حَسَنَةٌۭ","kebaikan"],["لِّمَن","untuk (dia) yang"],["كَانَ","ialah"],["يَرْجُوا۟","penuh harapan"],["ٱللَّهَ","(dalam) Allah"],["وَٱلْيَوْمَ","dan Hari"],["ٱلْـَٔاخِرَ ۚ","yang Terakhir"],["وَمَن","Dan sesiapa"],["يَتَوَلَّ","berpaling"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْغَنِىُّ","(adalah) Bebas daripada keperluan"],["ٱلْحَمِيدُ","yang Terpuji"]]],"5157":["(Mudah-mudahan Allah menimbulkan antara kalian dengan orang-orang yang kalian musuhi di antara mereka) yakni di antara orang-orang kafir Mekah, demi taat kepada perintah Allah swt. (kasih sayang) seumpamanya karena Allah memberikan petunjuk kepada mereka untuk beriman, karenanya mereka lalu menjadi teman-teman setia kalian. (Dan Allah adalah Maha Kuasa) untuk melakukan hal tersebut, dan ternyata Allah swt. melakukan hal tersebut sesudah penaklukan kota Mekah. (Dan Allah Maha Pengampun) kepada mereka atas kesalahan-kesalahan mereka di masa lalu sebelum mereka masuk Islam (lagi Maha Penyayang) terhadap mereka.",[["۞ عَسَى","barangkali"],["ٱللَّهُ","Allah"],["أَن","[bahawa]"],["يَجْعَلَ","akan meletakkan"],["بَيْنَكُمْ","antara kamu"],["وَبَيْنَ","dan antara"],["ٱلَّذِينَ","mereka (kepada) siapa"],["عَادَيْتُم","kamu telah menjadi musuh"],["مِّنْهُم","antara mereka"],["مَّوَدَّةًۭ ۚ","cinta"],["وَٱللَّهُ","Dan Allah"],["قَدِيرٌۭ ۚ","(adalah) Maha Kuasa"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"5158":["(Allah tiada melarang kalian terhadap orang-orang yang tidak memerangi kalian) dari kalangan orang-orang kafir (karena agama dan tidak mengusir kalian dari negeri kalian untuk berbuat baik kepada mereka) lafal an tabarruuhum menjadi badal isytimal dari lafal alladziina (dan berlaku adil) yaitu melakukan peradilan (terhadap mereka) dengan secara adil. Ayat ini diturunkan sebelum ada perintah untuk berjihad melawan mereka. (Sesungguhnya Allah menyukai orang-orang yang adil) yang berlaku adil.",[["لَّا","Tidak"],["يَنْهَىٰكُمُ","(ada) melarang kamu"],["ٱللَّهُ","Allah"],["عَنِ","daripada"],["ٱلَّذِينَ","orang yang"],["لَمْ","jangan"],["يُقَـٰتِلُوكُمْ","lawan kamu"],["فِى","dalam"],["ٱلدِّينِ","agama itu"],["وَلَمْ","dan jangan"],["يُخْرِجُوكُم","menghalau kamu keluar"],["مِّن","daripada"],["دِيَـٰرِكُمْ","rumah kamu"],["أَن","bahawa"],["تَبَرُّوهُمْ","kamu berurusan dengan baik"],["وَتُقْسِطُوٓا۟","dan berurusan dengan adil"],["إِلَيْهِمْ ۚ","bersama mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلْمُقْسِطِينَ","mereka yang berlaku adil"]]],"5159":["(Sesungguhnya Allah hanya melarang kalian terhadap orang-orang yang memerangi kalian karena agama dan mengusir kalian dari negeri kalian dan membantu) yakni menolong orang lain (untuk mengusir kalian untuk menjadikan mereka sebagai kawan kalian) lafal An Tawallauhum menjadi Badal Isytimal dari lafal Al Ladzina, yakni Dia melarang kalian untuk menjadikan mereka sebagai teman-teman setia kalian. (Dan barang siapa menjadikan mereka sebagai kawan, maka mereka itulah orang-orang yang lalim).",[["إِنَّمَا","Hanya"],["يَنْهَىٰكُمُ","melarang kamu"],["ٱللَّهُ","Allah"],["عَنِ","daripada"],["ٱلَّذِينَ","orang yang"],["قَـٰتَلُوكُمْ","lawan kamu"],["فِى","dalam"],["ٱلدِّينِ","agama itu"],["وَأَخْرَجُوكُم","dan menghalau kamu keluar"],["مِّن","daripada"],["دِيَـٰرِكُمْ","rumah kamu"],["وَظَـٰهَرُوا۟","dan sokongan"],["عَلَىٰٓ","dalam"],["إِخْرَاجِكُمْ","pengusiran kamu"],["أَن","bahawa"],["تَوَلَّوْهُمْ ۚ","kamu jadikan mereka sekutu"],["وَمَن","Dan sesiapa"],["يَتَوَلَّهُمْ","menjadikan mereka sekutu"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"5160":["(Hai orang-orang yang beriman, apabila datang kepada kalian perempuan-perempuan yang beriman) secara lisannya (untuk berhijrah) dari orang-orang kafir sesudah kalian mengadakan perjanjian perdamaian dengan orang-orang kafir dalam perjanjian Hudaibiah, yaitu bahwa barang siapa yang datang kepada orang-orang mukmin dari kalangan mereka, maka orang itu harus dikembalikan lagi kepada mereka (maka hendaklah kalian uji mereka) melalui sumpah, yaitu bahwa sesungguhnya mereka sekali-kali tidak keluar meninggalkan kampung halamannya melainkan karena senang kepada Islam, bukan karena benci terhadap suami mereka yang kafir, dan bukan pula karena mencintai orang-orang lelaki dari kalangan kaum muslimin. Demikianlah isi sumpah yang dilakukan oleh Nabi saw. kepada perempuan-perempuan itu (Allah telah mengetahui tentang keimanan mereka; maka jika kalian telah mengetahui, bahwa mereka) yakni kalian menduga melalui sumpah yang telah mereka ucapkan, bahwa mereka (benar-benar beriman maka janganlah kalian kembalikan mereka) janganlah kalian mengembalikan mereka (kepada orang-orang kafir. Mereka tidak halal bagi orang-orang kafir itu dan orang-orang kafir itu tiada halal pula bagi mereka. Dan berikanlah kepada mereka) yakni kembalikanlah kepada orang-orang kafir yang menjadi suami mereka (mahar yang telah mereka bayar) kepada perempuan-perempuan mukmin itu. (Dan tiada dosa atas kalian mengawini mereka) dengan syarat (apabila kalian bayar kepada mereka maharnya) maskawinnya. (Dan janganlah kalian tetap berpegang) dapat dibaca tumsikuu, dan tumassikuu yakni dengan memakai tasydid dan tanpa tasydid (pada tali perkawinan dengan perempuan-perempuan kafir) yakni istri-istri kalian yang kafir, karena keislaman kalian telah memutuskannya dari kalian berikut syarat-syaratnya. Atau perempuan-perempuan yang menyusul atau mengikuti orang-orang musyrik dalam keadaan murtad, karena kemurtadannya telah memutuskan tali perkawinan mereka dengan kalian, berikut syarat-syaratnya (dan hendaklah kalian minta) hendaklah kalian tuntut (apa yang telah kalian nafkahkan) kepada mereka yaitu mahar-mahar yang telah kalian bayar kepada mereka, berupa pengembalian dari orang-orang kafir yang mengawini mereka (dan hendaklah mereka meminta mahar yang telah mereka bayar) kepada perempuan-perempuan yang ikut berhijrah, sebagaimana penjelasan yang telah lalu yaitu bahwasanya kaum musliminlah yang membayarkannya. (Demikianlah hukum Allah yang ditetapkan-Nya di antara kalian) untuk kalian laksanakan. (Dan Allah Maha Mengetahui lagi Maha Bijaksana).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِذَا","Apabila"],["جَآءَكُمُ","datang kepada kamu"],["ٱلْمُؤْمِنَـٰتُ","wanita yang beriman"],["مُهَـٰجِرَٰتٍۢ","(sebagai) pendatang"],["فَٱمْتَحِنُوهُنَّ ۖ","kemudian periksa mereka"],["ٱللَّهُ","Allah"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِإِيمَـٰنِهِنَّ ۖ","iman mereka"],["فَإِنْ","Dan jika"],["عَلِمْتُمُوهُنَّ","kamu mengenali mereka"],["مُؤْمِنَـٰتٍۢ","(menjadi) orang yang beriman"],["فَلَا","maka (buat) jangan"],["تَرْجِعُوهُنَّ","pulangkan mereka"],["إِلَى","kepada"],["ٱلْكُفَّارِ ۖ","orang kafir"],["لَا","Tidak"],["هُنَّ","mereka"],["حِلٌّۭ","(adalah) halal"],["لَّهُمْ","bagi mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحِلُّونَ","adalah halal"],["لَهُنَّ ۖ","bagi mereka"],["وَءَاتُوهُم","Tetapi berikan mereka"],["مَّآ","apa"],["أَنفَقُوا۟ ۚ","mereka telah belanjakan"],["وَلَا","Dan tidak"],["جُنَاحَ","sebarang kesalahan"],["عَلَيْكُمْ","ke atas kamu"],["أَن","jika"],["تَنكِحُوهُنَّ","kamu kahwini mereka"],["إِذَآ","apabila"],["ءَاتَيْتُمُوهُنَّ","kamu telah memberi mereka"],["أُجُورَهُنَّ ۚ","iuran mereka (pengantin)."],["وَلَا","Dan jangan"],["تُمْسِكُوا۟","tahan"],["بِعِصَمِ","kepada ikatan perkahwinan"],["ٱلْكَوَافِرِ","(dengan) wanita kafir"],["وَسْـَٔلُوا۟","tetapi minta (untuk)"],["مَآ","apa"],["أَنفَقْتُمْ","kamu telah membelanjakan"],["وَلْيَسْـَٔلُوا۟","dan biarkan mereka bertanya"],["مَآ","apa"],["أَنفَقُوا۟ ۚ","mereka telah belanjakan"],["ذَٰلِكُمْ","Itu"],["حُكْمُ","(ialah) Penghakiman"],["ٱللَّهِ ۖ","(milik) Allah"],["يَحْكُمُ","Dia menilai"],["بَيْنَكُمْ ۚ","antara kamu"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","(adalah) Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"5161":["(Dan jika seseorang dari istri-istri kalian lari) seorang atau lebih di antara istri-istri kalian. Atau sebagian dari mahar mereka luput dari kalian, karena mereka lari (kepada orang-orang kafir) dalam keadaan murtad (lalu kalian mengalahkan mereka) maksudnya, memerangi mereka kemudian kalian memperoleh ganimah (maka bayarkanlah kepada orang-orang yang istrinya lari itu) dari ganimah yang kalian peroleh (mahar sebanyak yang telah mereka bayar) karena sebagian dari mahar tersebut tidak sempat mereka terima dari pihak orang-orang kafir. (Dan bertakwalah kepada Allah Yang kepada-Nya kalian beriman) kemudian orang-orang mukmin itu benar-benar mengerjakan apa yang telah diperintahkan kepada mereka, yaitu memberikan ganti rugi mahar kepada orang-orang kafir, dan juga kepada orang-orang mukmin yang istrinya lari, kemudian hukum ini sesudah itu ditiadakan.",[["وَإِن","Dan jika"],["فَاتَكُمْ","telah pergi dari kamu"],["شَىْءٌۭ","sebarang"],["مِّنْ","daripada"],["أَزْوَٰجِكُمْ","isteri-isteri kamu"],["إِلَى","kepada"],["ٱلْكُفَّارِ","orang kafir"],["فَعَاقَبْتُمْ","kemudian giliran kamu tiba"],["فَـَٔاتُوا۟","kemudian berikan"],["ٱلَّذِينَ","(kepada) mereka yang"],["ذَهَبَتْ","telah pergi"],["أَزْوَٰجُهُم","isteri mereka"],["مِّثْلَ","(yang) seperti"],["مَآ","apa"],["أَنفَقُوا۟ ۚ","mereka telah menghabiskan"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["ٱلَّذِىٓ","(dalam) Siapa"],["أَنتُم","kamu"],["بِهِۦ","[dalam Dia]"],["مُؤْمِنُونَ","(adalah) orang yang beriman"]]],"5162":["(Hai nabi, apabila datang kepada kamu perempuan-perempuan yang beriman untuk mengadakan janji setia, bahwa mereka tidak akan mempersekutukan sesuatu pun dengan Allah, tidak akan mencuri tidak akan berzina, tidak akan membunuh anak-anaknya) sebagaimana yang biasa mereka lakukan di zaman jahiliah, yaitu mengubur hidup-hidup bayi perempuan mereka, karena takut tercela dan takut jatuh miskin (dan tidak akan berbuat dusta yang mereka ada-adakan antara tangan dan kaki mereka) seumpamanya mereka memungut seorang anak, kemudian mereka mengaitkan anak itu sebagai hasil hubungannya dengan suami, lalu anak itu dipredikatkan sebagai anak kandungnya sendiri. Karena sesungguhnya seorang ibu itu apabila melahirkan anaknya, berarti anak itu adalah anak kandungnya sendiri yang keluar dari antara tangan dan kakinya, yakni dari perutnya (dan tidak akan mendurhakaimu dalam) pekerjaan (yang makruf) pekerjaan yang makruf artinya perbuatan yang sesuai dengan ketaatan kepada Allah, seperti meninggalkan niahah atau menjerit-jerit seraya menangis, menyobek-nyobek kerah baju, mengawut-awutkan rambut, dan mencakar-cakar muka, yang semuanya itu dilakukan di kala mereka ditinggal mati oleh suami atau keluarga mereka (maka terimalah janji setia mereka) Nabi saw. melantik janji setia mereka hanya melalui ucapan saja tanpa bersalaman atau berjabatan tangan dengan seseorang pun di antara mereka (dan mohonkanlah ampunan kepada Allah untuk mereka. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّبِىُّ","Nabi"],["إِذَا","Apabila"],["جَآءَكَ","datang kepada kamu"],["ٱلْمُؤْمِنَـٰتُ","wanita yang beriman"],["يُبَايِعْنَكَ","berikrar kepada kamu"],["عَلَىٰٓ","[pada]"],["أَن","bahawa"],["لَّا","tidak"],["يُشْرِكْنَ","mereka akan bergaul"],["بِٱللَّهِ","dengan Allah"],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["يَسْرِقْنَ","mereka akan mencuri"],["وَلَا","dan bukan"],["يَزْنِينَ","mereka akan berzina"],["وَلَا","dan bukan"],["يَقْتُلْنَ","mereka akan membunuh"],["أَوْلَـٰدَهُنَّ","anak-anak mereka"],["وَلَا","dan bukan"],["يَأْتِينَ","mereka bawa"],["بِبُهْتَـٰنٍۢ","fitnah"],["يَفْتَرِينَهُۥ","mereka menciptanya"],["بَيْنَ","antara"],["أَيْدِيهِنَّ","tangan mereka"],["وَأَرْجُلِهِنَّ","dan kaki mereka"],["وَلَا","dan bukan"],["يَعْصِينَكَ","mereka akan menderhaka kepadamu"],["فِى","dalam"],["مَعْرُوفٍۢ ۙ","(yang) betul"],["فَبَايِعْهُنَّ","maka terimalah ikrar mereka"],["وَٱسْتَغْفِرْ","dan memohon ampun"],["لَهُنَّ","bagi mereka"],["ٱللَّهَ ۖ","(dari) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"5163":["(Hai orang-orang yang beriman! Janganlah kalian jadikan penolong kalian kaum yang Allah murka terhadap mereka) yaitu orang-orang Yahudi (sesungguhnya mereka telah putus asa terhadap negeri akhirat) yakni dari pahala akhirat, padahal mereka meyakini adanya hari akhirat; demikian itu karena mereka ingkar kepada Nabi saw. padahal mereka mengetahui, bahwa Nabi saw. itu adalah benar (sebagaimana telah berputus asa orang-orang kafir) yang kini berada (dalam kubur) yaitu orang-orang kafir yang telah mati terkubur, telah putus asa dari kebaikan akhirat. Demikian itu karena di dalam kubur diperlihatkan kepada mereka tempat kedudukan mereka di surga seandainya mereka beriman, sebagaimana diperlihatkan pula kepada mereka tempat kembali yang akan mereka tempati, yaitu neraka.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَتَوَلَّوْا۟","buat sekutu"],["قَوْمًا","(dari) suatu kaum"],["غَضِبَ","(The) kemurkaan"],["ٱللَّهُ","(milik) Allah"],["عَلَيْهِمْ","(ada) atas mereka"],["قَدْ","Sesungguhnya"],["يَئِسُوا۟","mereka putus asa"],["مِنَ","daripada"],["ٱلْـَٔاخِرَةِ","akhirat"],["كَمَا","seperti"],["يَئِسَ","putus asa"],["ٱلْكُفَّارُ","orang kafir"],["مِنْ","daripada"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلْقُبُورِ","(dari) kubur"]]],"5164":["(Telah bertasbih kepada Allah apa saja yang ada di langit dan apa saja yang ada di bumi) yakni semuanya memahasucikan-Nya. Huruf lam yang terdapat pada lafal lillaah adalah huruf zaidah; dan di sini dipakai lafal maa, karena lebih memprioritaskan yang mayoritas (dan Dialah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam perbuatan-Nya.",[["سَبَّحَ","Memuliakan"],["لِلَّهِ","Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۖ","bumi"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5165":["(Hai orang-orang yang beriman mengapa kalian mengatakan) sewaktu kalian meminta berjihad (apa yang tidak kalian perbuat) karena ternyata kalian mengalami kekalahan atau mundur dalam perang Uhud.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["ءَامَنُوا۟","beriman"],["لِمَ","kenapa"],["تَقُولُونَ","(adakah) kamu katakan"],["مَا","apa"],["لَا","tidak"],["تَفْعَلُونَ","kamu lakukan"]]],"5166":["(Amat besar) yakni besar sekali (kebencian) lafal maqtan berfungsi menjadi tamyiz (di sisi Allah bahwa kalian mengatakan) lafal an taquuluu menjadi fa'il dari lafal kabura (apa-apa yang tiada kalian kerjakan).",[["كَبُرَ","Hebat"],["مَقْتًا","kebencian"],["عِندَ","dengan"],["ٱللَّهِ","Allah"],["أَن","bahawa"],["تَقُولُوا۟","kamu cakap"],["مَا","apa"],["لَا","tidak"],["تَفْعَلُونَ","kamu lakukan"]]],"5167":["(Sesungguhnya Allah menyukai) artinya selalu menolong dan memuliakan (orang-orang yang berperang di jalannya dalam barisan yang teratur) lafal shaffan merupakan hal atau kata keterangan keadaan, yakni dalam keadaan berbaris rapi (seakan-akan mereka seperti bangunan yang tersusun kokoh) yakni sebagian di antara mereka menempel rapat dengan sebagian yang lain lagi kokoh.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلَّذِينَ","orang yang"],["يُقَـٰتِلُونَ","bergaduh"],["فِى","dalam"],["سَبِيلِهِۦ","CaraNya"],["صَفًّۭا","(dalam) sebaris"],["كَأَنَّهُم","seolah-olah mereka"],["بُنْيَـٰنٌۭ","(adalah) struktur"],["مَّرْصُوصٌۭ","bergabung dengan kukuh"]]],"5168":["(Dan) ingatlah (ketika Musa berkata kepada kaumnya, \"Hai kaumku! Mengapa kalian menyakitiku?) mereka mengatakan bahwa Nabi Musa itu orang yang besar buah pelirnya atau berpenyakit burut, padahal kenyataannya tidaklah demikian, dan mereka pun mendustakannya (padahal sesungguhnya) lafal qad di sini menunjukkan makna tahqiq (kalian mengetahui, bahwa aku adalah utusan Allah kepada kalian.\") Kalimat wa qad ta`lamuuna dan seterusnya berkedudukan menjadi hal atau kata keterangan keadaan. Dan seorang yang menjadi rasul itu seharusnya kalian hormati. (Maka tatkala mereka berpaling) maksudnya menyimpang dari kebenaran, karena mereka telah menyakitinya (Allah memalingkan hati mereka) dari jalan petunjuk, sesuai dengan apa yang telah ditetapkan-Nya di zaman azali (dan Allah tiada memberi petunjuk kepada kaum yang fasik) yakni orang-orang yang kafir, menurut ilmu dan pengetahuan-Nya.",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦ","kepada umatnya"],["يَـٰقَوْمِ","Wahai kaumku"],["لِمَ","kenapa"],["تُؤْذُونَنِى","adakah kamu menyakiti aku"],["وَقَد","sedangkan pastinya"],["تَّعْلَمُونَ","kamu tahu"],["أَنِّى","bahawa aku"],["رَسُولُ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["إِلَيْكُمْ ۖ","kepada kamu"],["فَلَمَّا","Kemudian apabila"],["زَاغُوٓا۟","mereka menyimpang"],["أَزَاغَ","(disebabkan) menyimpang"],["ٱللَّهُ","(oleh) Allah"],["قُلُوبَهُمْ ۚ","hati mereka"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"5169":["(Dan) ingatlah (ketika Isa putra Maryam berkata, \"Hai Bani Israel!) di sini Nabi Isa tidak mengatakan hai kaumku, karena sesungguhnya dia tidak mempunyai kerabat di kalangan mereka (Sesungguhnya aku adalah utusan Allah kepada kalian, membenarkan kitab sebelumku) kitab yang diturunkan sebelumku (yaitu Taurat dan memberi kabar gembira dengan datangnya seorang rasul yang akan datang sesudahku, namanya Ahmad.\") Allah berfirman: (Maka tatkala rasul itu datang kepada mereka) yakni Ahmad alias Muhammad kepada orang-orang kafir (dengan membawa bukti-bukti yang nyata) yakni ayat-ayat dan tanda-tanda (mereka berkata, \"Ini) maksudnya, apa yang didatangkannya itu (adalah sihir) menurut suatu qiraat lafal sihrun dibaca saahirun artinya orang yang datang ini adalah penyihir (yang nyata\") yang jelas.",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["عِيسَى","Isa"],["ٱبْنُ","nak"],["مَرْيَمَ","(dari) Maryam"],["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["إِنِّى","Memang aku"],["رَسُولُ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["إِلَيْكُم","kepada kamu"],["مُّصَدِّقًۭا","mengesahkan"],["لِّمَا","itu yang"],["بَيْنَ","(adalah) antara"],["يَدَىَّ","tangan aku"],["مِنَ","daripada"],["ٱلتَّوْرَىٰةِ","Taurat"],["وَمُبَشِّرًۢا","dan membawa khabar gembira"],["بِرَسُولٍۢ","(dari) seorang Rasul"],["يَأْتِى","untuk datang"],["مِنۢ","daripada"],["بَعْدِى","selepas aku"],["ٱسْمُهُۥٓ","nama siapa (akan)"],["أَحْمَدُ ۖ","Ahmad"],["فَلَمَّا","Tetapi apabila"],["جَآءَهُم","dia datang kepada mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["قَالُوا۟","mereka berkata"],["هَـٰذَا","Ini"],["سِحْرٌۭ","(adalah) sihir"],["مُّبِينٌۭ","yang nyata"]]],"5170":["(Dan siapakah) artinya tiada seseorang pun (yang lebih zalim) maksudnya lebih besar kezalimannya (daripada orang yang mengada-adakan dusta terhadap Allah) yakni dengan cara menisbatkan adanya sekutu bagi-Nya, menyebutkan-Nya bahwa Dia mempunyai anak dan mengatakan ayat-ayat-Nya sebagai sihir (sedangkan dia diajak kepada agama Islam? Dan Allah tiada memberi petunjuk kepada orang-orang yang zalim) kepada orang-orang yang kafir.",[["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih salah"],["مِمَّنِ","daripada (seorang) yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","ke atas"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","pembohongan itu"],["وَهُوَ","sedangkan dia"],["يُدْعَىٰٓ","dijemput"],["إِلَى","kepada"],["ٱلْإِسْلَـٰمِ ۚ","Islam"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلظَّـٰلِمِينَ","[orang-orang] yang zalim"]]],"5171":["(Mereka hendak memadamkan) lafal liyuthfi'uu dinashabkan oleh an yang keberadaannya diperkirakan, sedangkan huruf lam-nya adalah zaidah (cahaya Allah) yakni syariat dan bukti-bukti-Nya (dengan mulut mereka) melalui ucapan-ucapan mereka bahwa Alquran itu adalah sihir, syair dan ramalan atau tenungan (dan Allah tetap menyempurnakan) artinya memenangkan atau menampakkan (cahaya-Nya) menurut suatu qiraat dibaca mutimmu nuurihi dengan dimudhafkan (meskipun orang-orang kafir benci) akan hal tersebut.",[["يُرِيدُونَ","Mereka berniat"],["لِيُطْفِـُٔوا۟","untuk memadam"],["نُورَ","(the) cahaya"],["ٱللَّهِ","(milik) Allah"],["بِأَفْوَٰهِهِمْ","dengan mulut mereka"],["وَٱللَّهُ","tetapi Allah"],["مُتِمُّ","akan menyempurnakan"],["نُورِهِۦ","CahayaNya"],["وَلَوْ","walaupun"],["كَرِهَ","tidak suka"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"5172":["(Dialah Yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang benar agar Dia memenangkannya) maksudnya menjadikannya berada di (atas segala agama-agama) yakni di atas semua agama yang bertentangan dengannya (meskipun orang-orang musyrik benci) akan hal tersebut.",[["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَرْسَلَ","dihantar"],["رَسُولَهُۥ","RasulNya"],["بِٱلْهُدَىٰ","dengan bimbingan"],["وَدِينِ","dan (agama) itu"],["ٱلْحَقِّ","(dari) kebenaran"],["لِيُظْهِرَهُۥ","untuk menjadikannya menang"],["عَلَى","atas"],["ٱلدِّينِ","agama itu"],["كُلِّهِۦ","kesemuanya"],["وَلَوْ","walaupun"],["كَرِهَ","tidak suka (ia)"],["ٱلْمُشْرِكُونَ","orang musyrik"]]],"5173":["(Hai orang-orang yang beriman, sukakah kalian Aku tunjukkan suatu perniagaan yang dapat menyelamatkan kalian) dapat dibaca tunjiikum dan tunajjiikum, yakni tanpa memakai tasydid dan dengan memakainya (dari azab yang pedih) yang menyakitkan; mereka seolah-olah menjawab, mengiyakan. Lalu Allah melanjutkan firman-Nya:",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["ءَامَنُوا۟","beriman"],["هَلْ","hendaklah"],["أَدُلُّكُمْ","aku bimbing kamu"],["عَلَىٰ","kepada"],["تِجَـٰرَةٍۢ","sesuatu transaksi"],["تُنجِيكُم","(itu) akan menyelamatkan kamu"],["مِّنْ","daripada"],["عَذَابٍ","azab"],["أَلِيمٍۢ","yang pedih"]]],"5174":["(Yaitu kalian beriman) artinya kalian tetap beriman (kepada Allah dan Rasul-Nya dan berjihad di jalan Allah dengan harta dan jiwa kalian. Itulah yang lebih baik bagi kalian jika kalian mengetahui) bahwasanya hal ini lebih baik bagi kalian, maka kerjakanlah.",[["تُؤْمِنُونَ","Percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَتُجَـٰهِدُونَ","dan berusaha"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["بِأَمْوَٰلِكُمْ","dengan kekayaan kamu"],["وَأَنفُسِكُمْ ۚ","dan kehidupan kamu"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"5175":["(Niscaya Allah akan mengampuni) menjadi jawab dari syarat yang diperkirakan keberadaannya; lengkapnya, jika kalian mengerjakannya, niscaya Dia akan mengampuni (dosa-dosa kalian dan memasukkan kalian ke dalam surga yang mengalir di bawahnya sungai-sungai dan memasukkan kalian ke tempat-tempat tinggal yang baik di dalam surga Adn) sebagai tempat menetap. (Itulah keberuntungan yang besar).",[["يَغْفِرْ","Dia akan memaafkan"],["لَكُمْ","bagi kamu"],["ذُنُوبَكُمْ","dosa kamu"],["وَيُدْخِلْكُمْ","dan mengakui kamu"],["جَنَّـٰتٍۢ","(dalam) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["وَمَسَـٰكِنَ","dan tempat tinggal"],["طَيِّبَةًۭ","menyenangkan"],["فِى","dalam"],["جَنَّـٰتِ","Taman-taman"],["عَدْنٍۢ ۚ","(dari) Keabadian"],["ذَٰلِكَ","Itu"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"5176":["(Dan) Dia memberikan kepada kalian nikmat (yang lain yang kalian sukai, yaitu pertolongan dari Allah dan kemenangan yang dekat waktunya. Dan sampaikanlah berita gembira kepada orang-orang yang beriman) yaitu berita tentang mendapat pertolongan dan kemenangan.",[["وَأُخْرَىٰ","Dan satu lagi"],["تُحِبُّونَهَا ۖ","yang kamu sayang"],["نَصْرٌۭ","bantuan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَفَتْحٌۭ","dan kemenangan"],["قَرِيبٌۭ ۗ","dekat"],["وَبَشِّرِ","dan sampaikanlah berita gembira"],["ٱلْمُؤْمِنِينَ","(kepada) orang-orang yang beriman"]]],"5177":["(Hai orang-orang yang beriman jadilah kalian penolong-penolong Allah) yakni agama-Nya; menurut suatu qiraat dibaca anshaarallah, artinya dengan dimudhafkan (sebagaimana telah dikatakan) dan seterusnya; makna yang dimaksud ialah sebagaimana yang telah dikatakan oleh kaum Hawariyyun. Pengertian ini disimpulkan dari ayat selanjutnya, yaitu (oleh Isa putra Maryam kepada pengikut-pengikutnya yang setia, \"Siapakah yang akan menjadi penolong-penolongku untuk menegakkan agama Allah?\") di antara orang-orang yang bersamaku. (Pengikut-pengikut yang setia itu berkata, \"Kami-lah penolong-penolong agama Allah\") penolong-penolong atau Hawariyyun adalah teman-teman pilihan Nabi Isa, mereka adalah orang-orang yang paling pertama dan paling dahulu beriman kepada Nabi Isa, dan jumlah mereka ada dua belas orang laki-laki. Lafal Hawariyyun ini diambil dari asal kata al-hur yang artinya putih cemerlang. Akan tetapi menurut suatu pendapat yang lain dikatakan, adalah terdiri dari orang-orang yang pendek dan pakaian mereka dicelup dengan warna putih (lalu segolongan dari Bani Israel beriman) kepada Nabi Isa, dan mereka mengatakan, bahwa Nabi Isa itu adalah hamba Allah yang kemudian diangkat naik ke langit (dan segolongan yang lain kafir) karena mereka telah mengatakan, bahwasanya Nabi Isa itu adalah anak Allah, yang kemudian diangkat ke langit ke sisi-Nya. Akhirnya kedua golongan tersebut berperang (maka Kami berikan kekuatan) Kami jadikan kuat (orang-orang yang beriman) di antara dua golongan tersebut (terhadap musuh-musuh mereka) yakni golongan yang kafir (lalu mereka menjadi orang-orang yang menang) memperoleh kemenangan atas golongan yang kafir",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["كُونُوٓا۟","Jadilah"],["أَنصَارَ","pembantu"],["ٱللَّهِ","(milik) Allah"],["كَمَا","seperti"],["قَالَ","berkata"],["عِيسَى","Isa"],["ٱبْنُ","nak"],["مَرْيَمَ","(dari) Maryam"],["لِلْحَوَارِيِّـۧنَ","kepada murid-murid"],["مَنْ","Siapa"],["أَنصَارِىٓ","(adalah) penolongku"],["إِلَى","bagi"],["ٱللَّهِ ۖ","Allah"],["قَالَ","Berkata"],["ٱلْحَوَارِيُّونَ","para murid"],["نَحْنُ","Kami"],["أَنصَارُ","(adalah) penolong-penolong"],["ٱللَّهِ ۖ","(milik) Allah"],["فَـَٔامَنَت","Kemudian beriman"],["طَّآئِفَةٌۭ","satu kumpulan"],["مِّنۢ","daripada"],["بَنِىٓ","Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["وَكَفَرَت","dan kafir"],["طَّآئِفَةٌۭ ۖ","satu kumpulan"],["فَأَيَّدْنَا","Jadi Kami menyokong"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["عَلَىٰ","terhadap"],["عَدُوِّهِمْ","musuh mereka"],["فَأَصْبَحُوا۟","dan mereka menjadi"],["ظَـٰهِرِينَ","dominan"]]],"5178":["(Telah bertasbih kepada Allah) telah memahasucikan-Nya; huruf lam yang terdapat pada lafal lillaahi adalah huruf zaidah (apa yang ada di langit dan apa yang ada di bumi) pemakaian lafal maa di sini karena memprioritaskan yang mayoritas (Raja, Yang Maha Suci) yakni Maha Suci dari sifat-sifat yang tidak layak bagi-Nya (Yang Maha Perkasa lagi Maha Bijaksana) di dalam kerajaan dan dalam perbuatan-Nya.",[["يُسَبِّحُ","Memuliakan"],["لِلَّهِ","Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["ٱلْمَلِكِ","Yang Berdaulat"],["ٱلْقُدُّوسِ","yang Suci"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْحَكِيمِ","Yang Maha Bijaksana"]]],"5179":["(Dialah yang mengutus kepada kaum yang buta huruf) yaitu bangsa Arab; lafal ummiy artinya orang yang tidak dapat menulis dan membaca kitab (seorang rasul di antara mereka) yaitu Nabi Muhammad saw. (yang membacakan kepada mereka ayat-ayat-Nya) yakni Alquran (menyucikan mereka) membersihkan mereka dari kemusyrikan (dan mengajarkan kepada mereka Kitab) Alquran (dan hikmah) yaitu hukum-hukum yang terkandung di dalamnya, atau hadis. (Dan sesungguhnya) lafal in di sini adalah bentuk takhfif dari inna, sedangkan isimnya tidak disebutkan selengkapnya; dan sesungguhnya (mereka adalah sebelumnya) sebelum kedatangan Nabi Muhammad saw. (benar-benar dalam kesesatan yang nyata) artinya jelas sesatnya.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["بَعَثَ","dihantar"],["فِى","antara"],["ٱلْأُمِّيِّـۧنَ","yang tidak bersurat"],["رَسُولًۭا","seorang Rasul"],["مِّنْهُمْ","daripada diri mereka sendiri"],["يَتْلُوا۟","mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِهِۦ","Ayat-ayatNya"],["وَيُزَكِّيهِمْ","dan menyucikan mereka"],["وَيُعَلِّمُهُمُ","dan mengajar mereka"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحِكْمَةَ","dan hikmahnya"],["وَإِن","walaupun"],["كَانُوا۟","mereka adalah"],["مِن","daripada"],["قَبْلُ","sebelum"],["لَفِى","pasti masuk"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","yang nyata"]]],"5180":["(Dan juga kepada kaum yang lain) lafal ini diathafkan kepada lafal al-ummiyyiina, yakni orang-orang yang ada (dari mereka) yaitu orang-orang yang datang kemudian dari mereka, artinya sesudah mereka (tiadalah) (dapat menyusul para pendahulunya) yakni dalam hal kepeloporan dan keutamaannya. (Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana) di dalam kerajaan-Nya dan dalam perbuatan-Nya. Yang dimaksud dengan kaum yang lain ini adalah para tabiin; disebutkannya para sahabat secara khusus pada ayat sebelumnya merupakan dalil yang cukup untuk membuktikan keutamaan para sahabat karena mereka dapat bertemu langsung dengan Nabi saw. yang diutus kepada mereka. Keutamaan mereka jauh lebih besar daripada orang-orang yang datang kemudian sesudah mereka di antara orang-orang yang Nabi pun diutus kepada mereka, dan mereka beriman kepadanya baik dari jenis manusia maupun dari jenis jin hingga hari kiamat. Karena sesungguhnya setiap generasi itu jauh lebih baik daripada generasi penerusnya.",[["وَءَاخَرِينَ","Dan lain-lain"],["مِنْهُمْ","antara mereka"],["لَمَّا","yang belum lagi"],["يَلْحَقُوا۟","menyertai"],["بِهِمْ ۚ","mereka"],["وَهُوَ","dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5181":["(Demikianlah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya) yaitu kepada Nabi dan orang-orang yang disebutkan bersamanya (dan Allah mempunyai karunia yang besar).",[["ذَٰلِكَ","Itu"],["فَضْلُ","(ialah) Bounty"],["ٱللَّهِ","(milik) Allah"],["يُؤْتِيهِ","Dia memberikannya"],["مَن","(kepada) siapa"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik"],["ٱلْفَضْلِ","(dari) Bounty"],["ٱلْعَظِيمِ","yang Agung"]]],"5182":["(Perumpamaan orang-orang yang dipikulkan kepadanya kitab Taurat) mereka yang dibebani untuk mengamalkannya (kemudian mereka tidak memikulnya) tidak mengamalkannya, antara lain, mereka tidak beriman kepada perkara yang menyangkut sifat-sifat Nabi saw. sebagai nabi yang akan datang padahal telah terkandung di dalamnya. Mereka itu (adalah seperti keledai yang membawa kitab-kitab) yang dimaksud dengan sifir-sifir adalah kitab-kitab, dalam arti kata keledai itu tidak dapat memanfaatkannya. (Amatlah buruknya perumpamaan kaum yang mendustakan ayat-ayat Allah) yang membenarkan Nabi saw. Sedangkan subjek yang dicelanya tidak disebutkan, lengkapnya, seburuk-buruk perumpamaan kaum yang mendustakan ayat-ayat Allah adalah perumpamaan ini. (Dan Allah tiada memberi petunjuk kepada kaum yang lalim) yaitu kaum yang kafir.",[["مَثَلُ","(The) persamaan"],["ٱلَّذِينَ","orang yang"],["حُمِّلُوا۟","telah diamanahkan"],["ٱلتَّوْرَىٰةَ","(dengan) Taurat"],["ثُمَّ","kemudian"],["لَمْ","tidak"],["يَحْمِلُوهَا","mereka menanggungnya"],["كَمَثَلِ","(adalah) seperti"],["ٱلْحِمَارِ","keldai itu"],["يَحْمِلُ","yang membawa"],["أَسْفَارًۢا ۚ","buku"],["بِئْسَ","Malangnya"],["مَثَلُ","(the) contoh"],["ٱلْقَوْمِ","(daripada) rakyat"],["ٱلَّذِينَ","yang"],["كَذَّبُوا۟","menafikan"],["بِـَٔايَـٰتِ","(the) Tanda-tanda"],["ٱللَّهِ ۚ","(milik) Allah"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"5183":["(Katakanlah, \"Hai orang-orang yang menganut agama Yahudi! Jika kalian mendakwakan bahwa sesungguhnya kalian sajalah kekasih-kekasih Allah bukan manusia-manusia yang lain, maka harapkanlah kematian kalian, jika kalian adalah orang-orang yang benar\") kedua Syarat yang ada pada ayat ini, yakni lafal in za'amtum dan lafal in kuntum bertaalluq atau bergantung kepada lafal tamannau dalam arti kata bahwa syarat yang pertama menjadi qaid atau pengertian yang mengikat bagi syarat yang kedua. Artinya, jika kalian benar-benar di dalam dugaan kalian yang menganggap bahwa kalian adalah kekasih-kekasih Allah. Dan merupakan suatu kelaziman bagi kekasih Allah itu selalu mementingkan kehidupan di akhirat, dan permulaan jalan untuk menuju ke akhirat itu adalah mati; karena itu harapkanlah kematian itu.",[["قُلْ","Katakanlah"],["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","kamu (siapa)"],["هَادُوٓا۟","(adalah) Yahudi"],["إِن","Jika"],["زَعَمْتُمْ","kamu mendakwa"],["أَنَّكُمْ","bahawa kamu"],["أَوْلِيَآءُ","(adalah) sekutu"],["لِلَّهِ","daripada Allah"],["مِن","daripada"],["دُونِ","tidak termasuk"],["ٱلنَّاسِ","manusia"],["فَتَمَنَّوُا۟","maka berhajat"],["ٱلْمَوْتَ","(untuk) kematian"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"5184":["(Mereka tiada akan mengharapkan kematian itu selama-lamanya disebabkan kejahatan yang telah mereka perbuat dengan tangan-tangan mereka sendiri) yaitu berupa kekafiran mereka kepada Nabi saw. yang hal ini menunjukkan kepada kedustaan mereka terhadap ayat-ayat Allah. (Dan Allah Mengetahui orang-orang yang lalim) yakni orang-orang yang kafir.",[["وَلَا","Tetapi tidak"],["يَتَمَنَّوْنَهُۥٓ","mereka akan mengharapkannya"],["أَبَدًۢا","pernah"],["بِمَا","bagi apa"],["قَدَّمَتْ","(telah) menghantar"],["أَيْدِيهِمْ ۚ","tangan mereka"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِٱلظَّـٰلِمِينَ","daripada orang-orang yang zalim"]]],"5185":["(Katakanlah!, \"Sesungguhnya kematian yang kalian lari daripadanya, sesungguhnya kematian itu) huruf fa pada lafal fa-innahu adalah huruf zaidah (akan menemui kalian, kemudian kalian akan dikembalikan kepada Allah Yang Maha Mengetahui yang gaib dan yang nyata) artinya mengetahui pada yang rahasia dan terang-terangan (lalu Dia beritakan kepada kalian apa yang telah kalian kerjakan.\") maka Dia akan membalasnya kepada kalian.",[["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱلْمَوْتَ","kematian itu"],["ٱلَّذِى","yang"],["تَفِرُّونَ","kamu lari"],["مِنْهُ","daripadanya"],["فَإِنَّهُۥ","maka pastinya"],["مُلَـٰقِيكُمْ ۖ","(akan) bertemu kamu"],["ثُمَّ","Kemudian"],["تُرَدُّونَ","kamu akan dihantar balik"],["إِلَىٰ","kepada"],["عَـٰلِمِ","(yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang disaksikan"],["فَيُنَبِّئُكُم","dan Dia akan memberitahu kamu"],["بِمَا","[dari] apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"5186":["(Hai orang-orang yang beriman, apabila diseru untuk menunaikan salat pada) huruf min di sini bermakna fi, yakni pada (hari Jumat maka bersegeralah kalian) yakni cepat-cepatlah kalian berangkat (untuk mengingat Allah) yakni salat (dan tinggalkanlah jual beli) tinggalkanlah transaksi jual beli itu. (Yang demikian itu lebih baik bagi kalian jika kalian mengetahui) bahwasanya hal ini lebih baik, maka kerjakanlah ia.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["ءَامَنُوٓا۟","beriman"],["إِذَا","Apabila"],["نُودِىَ","(panggilan) dibuat"],["لِلصَّلَوٰةِ","untuk (sembahyang) itu"],["مِن","pada"],["يَوْمِ","(hari itu)."],["ٱلْجُمُعَةِ","(dari) hari Jumaat"],["فَٱسْعَوْا۟","maka bersegeralah"],["إِلَىٰ","kepada"],["ذِكْرِ","(the) zikir"],["ٱللَّهِ","(milik) Allah"],["وَذَرُوا۟","dan pergi"],["ٱلْبَيْعَ ۚ","perniagaan itu"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"5187":["(Apabila telah ditunaikan salat, maka bertebaranlah kalian di muka bumi) perintah ini menunjukkan pengertian ibahah atau boleh (dan carilah) carilah rezeki (karunia Allah, dan ingatlah Allah) dengan ingatan (sebanyak-banyaknya supaya kalian beruntung) yakni memperoleh keberuntungan. Pada hari Jumat, Nabi saw. berkhutbah akan tetapi tiba-tiba datanglah rombongan kafilah membawa barang-barang dagangan, lalu dipukullah genderang menyambut kedatangannya sebagaimana biasanya. Maka orang-orang pun berhamburan keluar dari mesjid untuk menemui rombongan itu, kecuali hanya dua belas orang saja yang masih tetap bersama Nabi saw. lalu turunlah ayat ini.",[["فَإِذَا","Kemudian apabila"],["قُضِيَتِ","disimpulkan"],["ٱلصَّلَوٰةُ","solat"],["فَٱنتَشِرُوا۟","kemudian bersurai"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَٱبْتَغُوا۟","dan cari"],["مِن","daripada"],["فَضْلِ","(the) Bounty"],["ٱللَّهِ","(milik) Allah"],["وَٱذْكُرُوا۟","dan ingat"],["ٱللَّهَ","Allah"],["كَثِيرًۭا","banyak"],["لَّعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","berjaya"]]],"5188":["(Dan apabila mereka melihat perniagaan atau permainan, mereka bubar untuk menuju kepadanya) yakni kepada barang dagangan, karena barang dagangan itu merupakan kebutuhan yang mereka perlukan, berbeda dengan permainan (dan mereka tinggalkan kamu) dalam khotbahmu (dalam keadaan berdiri. Katakanlah, \"Apa yang di sisi Allah) berupa pahala (lebih baik) bagi orang-orang yang beriman (dari permainan dan perniagaan,\" dan Allah sebaik-baik pemberi rezeki) bila dikatakan, setiap orang itu memberi rezeki kepada keluarganya, maka pengertian yang dimaksud ialah dari rezeki Allah swt.",[["وَإِذَا","Dan apabila"],["رَأَوْا۟","mereka nampak"],["تِجَـٰرَةً","sesuatu transaksi"],["أَوْ","atau"],["لَهْوًا","satu sukan"],["ٱنفَضُّوٓا۟","mereka bergegas"],["إِلَيْهَا","kepadanya"],["وَتَرَكُوكَ","dan meninggalkan kamu"],["قَآئِمًۭا ۚ","berdiri"],["قُلْ","Katakanlah"],["مَا","Apa"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["خَيْرٌۭ","(lebih) baik"],["مِّنَ","daripada"],["ٱللَّهْوِ","sukan itu"],["وَمِنَ","dan daripada"],["ٱلتِّجَـٰرَةِ ۚ","(sebarang) transaksi"],["وَٱللَّهُ","Dan Allah"],["خَيْرُ","(adalah) Terbaik"],["ٱلرَّٰزِقِينَ","(dari) Pembekal"]]],"5189":["(Apabila orang-orang munafik datang kepadamu, mereka berkata) dengan mulut mereka mengenai hal-hal yang bertentangan dengan apa yang ada dalam hati mereka (\"Kami mengakui, bahwa sesungguhnya kamu benar-benar Rasul Allah.\" Dan Allah mengetahui bahwa sesungguhnya kamu benar-benar Rasul-Nya; dan Allah menyaksikan) yakni mengetahui (bahwa sesungguhnya orang-orang munafik itu benar-benar pendusta) yakni isi hati mereka berbeda dengan apa yang mereka katakan.",[["إِذَا","Apabila"],["جَآءَكَ","datang kepada kamu"],["ٱلْمُنَـٰفِقُونَ","golongan munafik"],["قَالُوا۟","mereka berkata"],["نَشْهَدُ","Kami bersaksi"],["إِنَّكَ","bahawa kamu"],["لَرَسُولُ","sesungguhnya (adalah) Rasul"],["ٱللَّهِ ۗ","(milik) Allah"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["إِنَّكَ","bahawa kamu"],["لَرَسُولُهُۥ","(adalah) sesungguhnya Rasul-Nya"],["وَٱللَّهُ","dan Allah"],["يَشْهَدُ","memberi keterangan"],["إِنَّ","bahawa"],["ٱلْمُنَـٰفِقِينَ","golongan munafik"],["لَكَـٰذِبُونَ","(adalah) sesungguhnya pendusta"]]],"5190":["(Mereka itu menjadikan sumpah mereka sebagai perisai) maksudnya untuk melindungi harta benda mereka dan jiwa mereka (lalu mereka menghalangi) melalui sumpah itu (jalan Allah) artinya mereka menghalangi manusia untuk berjihad melawan mereka. (Sesungguhnya amat buruklah apa yang telah mereka kerjakan).",[["ٱتَّخَذُوٓا۟","Mereka ambil"],["أَيْمَـٰنَهُمْ","sumpah mereka"],["جُنَّةًۭ","(sebagai) penutup"],["فَصَدُّوا۟","jadi mereka berpaling"],["عَن","daripada"],["سَبِيلِ","(cara)"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّهُمْ","Sesungguhnya [mereka]"],["سَآءَ","jahat adalah"],["مَا","apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"5191":["(Yang demikian itu) yakni pekerjaan mereka yang buruk itu (adalah karena sesungguhnya mereka telah beriman) mulutnya (kemudian menjadi kafir) hatinya. Artinya, mereka masih tetap dalam kekafirannya, (lalu dikunci matilah) dikuncilah (hati mereka) dengan kekafiran (karena itu mereka tidak dapat mengerti) tentang iman yang sesungguhnya.",[["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana"],["ءَامَنُوا۟","mereka beriman"],["ثُمَّ","kemudian"],["كَفَرُوا۟","mereka kafir"],["فَطُبِعَ","jadi telah dimeteraikan"],["عَلَىٰ","[atas]"],["قُلُوبِهِمْ","hati mereka"],["فَهُمْ","jadi mereka"],["لَا","jangan"],["يَفْقَهُونَ","faham"]]],"5192":["(Dan apabila kamu melihat mereka, tubuh-tubuh mereka menjadikan kamu kagum) karena keindahan dan kebagusannya. (Dan jika mereka berkata kamu mendengarkan perkataan mereka) karena kefasihan tutur katanya. (Mereka adalah seakan-akan) karena tubuhnya yang besar akan tetapi pikirannya kosong tidak dapat memahami (kayu) dapat dibaca khusyubun dan khusybun (yang tersandar) artinya bagaikan kayu yang tersandar ke tembok. (Mereka mengira bahwa tiap-tiap teriakan keras) teriakan sebagaimana seruan di dalam kemiliteran, atau bagaikan seruan orang yang mencari barang yang hilang (ditujukan kepada mereka) demikian itu karena hati mereka sudah memendam rasa kecut dan takut terhadap hal-hal yang akan menimpa mereka yang memperbolehkan darah mereka dialirkan. (Mereka itulah musuh yang sebenarnya, maka waspadalah terhadap mereka) karena sesungguhnya mereka pasti membeberkan rahasia kamu kepada orang-orang kafir (semoga Allah membinasakan mereka) menghancurkan mereka. (Bagaimanakah mereka sampai dipalingkan?) dari iman, padahal bukti-buktinya sudah cukup jelas.",[["۞ وَإِذَا","Dan apabila"],["رَأَيْتَهُمْ","kamu melihat mereka"],["تُعْجِبُكَ","menggembirakan kamu"],["أَجْسَامُهُمْ ۖ","badan mereka"],["وَإِن","dan jika"],["يَقُولُوا۟","mereka bercakap"],["تَسْمَعْ","kamu dengar"],["لِقَوْلِهِمْ ۖ","kepada ucapan mereka"],["كَأَنَّهُمْ","seolah-olah mereka (adalah)"],["خُشُبٌۭ","kepingan kayu"],["مُّسَنَّدَةٌۭ ۖ","disandarkan"],["يَحْسَبُونَ","Mereka berfikir"],["كُلَّ","setiap"],["صَيْحَةٍ","jerit"],["عَلَيْهِمْ ۚ","(adalah) menentang mereka"],["هُمُ","mereka"],["ٱلْعَدُوُّ","(adalah) musuh"],["فَٱحْذَرْهُمْ ۚ","jadi berhati-hatilah dengan mereka"],["قَـٰتَلَهُمُ","Boleh memusnahkan mereka"],["ٱللَّهُ ۖ","Allah"],["أَنَّىٰ","Bagaimana"],["يُؤْفَكُونَ","adakah mereka tertipu"]]],"5193":["(Dan apabila dikatakan kepada mereka, \"Marilah) seraya memberi maaf (supaya Rasulullah memberikan ampunan bagi kalian,\" mereka membuang) lafal lawwau dapat dibaca dengan memakai tasydid, dapat pula dibaca tanpa memakainya sehingga menjadi lawau, artinya memalingkan (muka mereka dan kamu lihat mereka berpaling) dari hal tersebut (sedangkan mereka menyombongkan diri).",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["تَعَالَوْا۟","Datang"],["يَسْتَغْفِرْ","akan meminta ampun"],["لَكُمْ","bagi kamu"],["رَسُولُ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["لَوَّوْا۟","Mereka berpaling ke tepi"],["رُءُوسَهُمْ","kepala mereka"],["وَرَأَيْتَهُمْ","dan kamu melihat mereka"],["يَصُدُّونَ","berpaling"],["وَهُم","sedangkan mereka"],["مُّسْتَكْبِرُونَ","(adalah) sombong"]]],"5194":["(Sama saja bagi mereka, kamu mintakan ampunan bagi mereka) dalam ungkapan kalimat astaghfarta, keberadaan hamzah istifham cukup diwakili oleh hamzah washal (atau kamu tidak memintakan ampunan bagi mereka, Allah tidak akan memberikan ampunan kepada mereka. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang fasik).",[["سَوَآءٌ","(Ia) adalah sama"],["عَلَيْهِمْ","bagi mereka"],["أَسْتَغْفَرْتَ","sama ada kamu meminta ampun"],["لَهُمْ","bagi mereka"],["أَمْ","atau"],["لَمْ","jangan"],["تَسْتَغْفِرْ","minta ampun"],["لَهُمْ","bagi mereka"],["لَن","tidak pernah"],["يَغْفِرَ","akan memaafkan"],["ٱللَّهُ","Allah"],["لَهُمْ ۚ","[kepada] mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"5195":["(Mereka orang-orang yang mengatakan) kepada teman-teman mereka dari kalangan kaum Ansar: (\"Janganlah kalian memberikan perbelanjaan kepada orang-orang yang ada di sisi Rasulullah) yakni orang-orang Muhajirin (supaya mereka bubar\") bercerai-berai dari sisinya. (Padahal kepunyaan Allahlah perbendaharaan langit dan bumi) yakni pemberian rezeki-Nya, Dia Maha Pemberi rezeki kepada orang-orang Muhajirin dan lain-lainnya (tetapi orang-orang munafik itu tidak memahami).",[["هُمُ","mereka"],["ٱلَّذِينَ","(adalah) mereka yang"],["يَقُولُونَ","berkata"],["لَا","Jangan"],["تُنفِقُوا۟","berbelanja"],["عَلَىٰ","pada"],["مَنْ","(mereka) yang"],["عِندَ","(ada) dengan"],["رَسُولِ","(the) Rasul"],["ٱللَّهِ","(milik) Allah"],["حَتَّىٰ","sehingga"],["يَنفَضُّوا۟ ۗ","mereka bubar"],["وَلِلَّهِ","Dan untuk Allah"],["خَزَآئِنُ","(adalah) khazanah"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَلَـٰكِنَّ","tetapi"],["ٱلْمُنَـٰفِقِينَ","golongan munafik"],["لَا","jangan"],["يَفْقَهُونَ","faham"]]],"5196":["(Mereka berkata, \"Sesungguhnya jika kita telah kembali) yakni kembali dari peperangan Bani Mushthaliq (ke Madinah, benar-benar orang yang kuat akan mengusir) yang dimaksud orang-orang kuat adalah diri mereka sendiri (orang-orang yang lemah daripadanya\") yang dimaksud oleh mereka adalah orang-orang mukmin. (Padahal kekuatan itu hanyalah bagi Allah) yakni kemenangan itu milik Allah (bagi Rasul-Nya dan bagi orang-orang mukmin, tetapi orang-orang munafik itu tidak mengetahui) hal tersebut.",[["يَقُولُونَ","Mereka berkata"],["لَئِن","Jika"],["رَّجَعْنَآ","kita balik"],["إِلَى","kepada"],["ٱلْمَدِينَةِ","Al-Madinah"],["لَيُخْرِجَنَّ","pasti, akan mengusir"],["ٱلْأَعَزُّ","yang lebih mulia"],["مِنْهَا","daripadanya"],["ٱلْأَذَلَّ ۚ","semakin merendah diri"],["وَلِلَّهِ","Tetapi kerana Allah"],["ٱلْعِزَّةُ","(ialah) kehormatan"],["وَلِرَسُولِهِۦ","dan untuk RasulNya"],["وَلِلْمُؤْمِنِينَ","dan bagi orang-orang yang beriman"],["وَلَـٰكِنَّ","tetapi"],["ٱلْمُنَـٰفِقِينَ","golongan munafik"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"5197":["(Hai orang-orang yang beriman, janganlah melalaikan kalian) yakni melupakan kalian (harta-harta kalian dan anak-anak kalian dari mengingat Allah) dari melakukan salat lima waktu. (Barang siapa yang berbuat demikian maka mereka itulah orang-orang yang rugi).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","kamu (siapa)"],["ءَامَنُوا۟","beriman"],["لَا","(Biar) jangan"],["تُلْهِكُمْ","alihkan kamu"],["أَمْوَٰلُكُمْ","kekayaan kamu"],["وَلَآ","dan bukan"],["أَوْلَـٰدُكُمْ","anak-anak kamu"],["عَن","daripada"],["ذِكْرِ","(the) zikir"],["ٱللَّهِ ۚ","(milik) Allah"],["وَمَن","Dan sesiapa"],["يَفْعَلْ","tidak"],["ذَٰلِكَ","bahawa"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"5198":["(Dan belanjakanlah) dalam berzakat (sebagian dari apa yang telah Kami berikan kepada kalian sebelum datang kematian kepada salah seorang di antara kalian; lalu ia berkata, \"Ya Rabbku! Mengapa tidak) lafal laula di sini bermakna halla, yakni kenapa tidak. Atau huruf la dianggap sebagai huruf zaidah dan huruf lau bermakna tamanni, yakni seandainya (Engkau menangguhkan aku sampai waktu yang dekat, yang menyebabkan aku dapat bersedekah) bentuk asli lafal ashshaddaqa adalah atashaddaqa, kemudian huruf ta diidghamkan ke dalam huruf shad sehingga jadilah ashshaddaqa, yakni supaya aku dapat membayar zakatku (dan aku termasuk orang-orang yang saleh?\") seumpamanya aku akan menunaikan ibadah haji. Ibnu Abbas r.a. telah memberikan penafsirannya, bahwa tiada seseorang pun yang melalaikan untuk membayar zakat dan melakukan ibadah haji, melainkan ia meminta supaya kematiannya ditangguhkan di saat ia menjelang ajalnya.",[["وَأَنفِقُوا۟","Dan belanjakan"],["مِن","daripada"],["مَّا","apa"],["رَزَقْنَـٰكُم","Kami telah menyediakan kamu"],["مِّن","daripada"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِىَ","datang"],["أَحَدَكُمُ","(kepada) salah seorang daripada kamu"],["ٱلْمَوْتُ","kematian itu"],["فَيَقُولَ","dan dia berkata"],["رَبِّ","Tuhanku"],["لَوْلَآ","kenapa tidak"],["أَخَّرْتَنِىٓ","Kamu lambatkan aku"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["قَرِيبٍۢ","dekat"],["فَأَصَّدَّقَ","jadi aku akan bersedekah"],["وَأَكُن","dan jadilah"],["مِّنَ","antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"5199":["(Dan Allah sekali-kali tidak akan menangguhkan, kematian, seseorang apabila datang waktu kematiannya. Dan Allah Maha Mengenal apa yang kalian kerjakan) lafal ta'maluuna dapat pula dibaca ya'maluuna, sehingga artinya menjadi, yang mereka kerjakan.",[["وَلَن","Tetapi tidak pernah"],["يُؤَخِّرَ","akan (akan) ditangguhkan"],["ٱللَّهُ","(oleh) Allah"],["نَفْسًا","sebuah jiwa"],["إِذَا","apabila"],["جَآءَ","telah datang"],["أَجَلُهَا ۚ","istilahnya"],["وَٱللَّهُ","Dan Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"5200":["(Bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi) artinya, semuanya memahasucikan Dia. Huruf lam pada lafal lillaahi adalah zaidah. Dan dalam ungkapan ayat ini dipakai huruf maa, hal ini tiada lain karena memprioritaskan yang mayoritas (hanya Allah lah yang mempunyai semua kerajaan dan semua puji-pujian, dan Dia Maha Kuasa atas segala sesuatu).",[["يُسَبِّحُ","Memuliakan"],["لِلَّهِ","[kepada] Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۖ","bumi"],["لَهُ","Untuk Dia"],["ٱلْمُلْكُ","(ialah) kekuasaan"],["وَلَهُ","dan untuk Dia"],["ٱلْحَمْدُ ۖ","(ialah) pujian"],["وَهُوَ","Dan Dia"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","Maha Berkuasa"]]],"5201":["(Dialah Yang menciptakan kalian maka di antara kalian ada yang kafir dan di antara kalian ada yang beriman) menurut asal kejadiannya, kemudian Dia mematikan kalian, lalu Dia menghidupkan kalian dalam keadaan seperti itu. (Dan Allah Maha Melihat apa yang kalian kerjakan).",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَكُمْ","mencipta kamu"],["فَمِنكُمْ","dan di antara kamu"],["كَافِرٌۭ","(adalah) seorang yang kafir"],["وَمِنكُم","dan di antara kamu"],["مُّؤْمِنٌۭ ۚ","(adalah) seorang yang beriman"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌ","(ialah) Maha Melihat"]]],"5202":["(Dia menciptakan langit dan bumi dengan, tujuan, yang benar. Dia membentuk rupa kalian dan dibaguskan-Nya rupa kalian itu) karena Dia telah menjadikan bentuk Bani Adam dalam bentuk yang paling baik dan rupa yang paling bagus (dan hanya kepada-Nyalah kembali).",[["خَلَقَ","Dia cipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ","dengan kebenaran"],["وَصَوَّرَكُمْ","dan Dia membentuk kamu"],["فَأَحْسَنَ","dan dibuat baik"],["صُوَرَكُمْ ۖ","borang kamu"],["وَإِلَيْهِ","dan kepada-Nya"],["ٱلْمَصِيرُ","(ialah) pulangan terakhir"]]],"5203":["(Dia mengetahui apa yang ada di langit dan apa yang ada di bumi, dan mengetahui apa yang kalian rahasiakan dan apa yang kalian nyatakan. Dan Allah Maha Mengetahui segala isi hati) semua rahasia dan keyakinan yang terpendam di dalamnya.",[["يَعْلَمُ","Dia tahu"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَيَعْلَمُ","dan Dia mengetahui"],["مَا","apa"],["تُسِرُّونَ","kamu sembunyikan"],["وَمَا","dan apa"],["تُعْلِنُونَ ۚ","kamu isytihar"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]],"5204":["(Apakah belum datang kepada kalian) hai orang-orang kafir Mekah (berita) atau cerita (tentang orang-orang kafir dahulu? Maka mereka telah merasakan akibat yang buruk dari perbuatan mereka) yaitu hukuman di dunia sebagai pembalasan dari kekafiran mereka (dan bagi mereka) di akhirat nanti (azab yang pedih) yang menyakitkan.",[["أَلَمْ","belum"],["يَأْتِكُمْ","datang kepada kamu"],["نَبَؤُا۟","(the) berita"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["قَبْلُ","sebelum"],["فَذَاقُوا۟","Jadi mereka rasa"],["وَبَالَ","(buruk) akibatnya"],["أَمْرِهِمْ","(dari) urusan mereka"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"5205":["(Yang demikian itu) atau azab di dunia itu (adalah karena sesungguhnya) dhamir yang terdapat dalam lafal annahu adalah dhamir sya'n (telah datang kepada mereka rasul-rasul mereka dengan membawa keterangan-keterangan yang nyata) hujah-hujah yang jelas yang menunjukkan kepada keimanan (lalu mereka berkata, \"Apakah manusia) yang dimaksud adalah jenisnya (yang akan memberi petunjuk kepada kami?\" Lalu mereka ingkar dan berpaling) dari keimanan (dan Allah tidak memerlukan) keimanan mereka. (Dan Allah Maha Kaya) dari makhluk-Nya (lagi Maha Terpuji) dalam perbuatan-perbuatan-Nya.",[["ذَٰلِكَ","Itu"],["بِأَنَّهُۥ","(adalah) kerana"],["كَانَت","telah"],["تَّأْتِيهِمْ","datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَقَالُوٓا۟","tetapi mereka berkata"],["أَبَشَرٌۭ","Hendaklah manusia"],["يَهْدُونَنَا","membimbing kami"],["فَكَفَرُوا۟","Maka kafirlah mereka"],["وَتَوَلَّوا۟ ۚ","dan berpaling"],["وَّٱسْتَغْنَى","Dan boleh melakukannya tanpa mereka"],["ٱللَّهُ ۚ","Allah"],["وَٱللَّهُ","Dan Allah"],["غَنِىٌّ","(adalah) Berdikari"],["حَمِيدٌۭ","terpuji"]]],"5206":["(Orang-orang yang kafir menduga, bahwa sesungguhnya) mereka. Lafal An di sini adalah bentuk Takhfif dari Anna sedangkan yang menjadi Isimnya tidak disebutkan, yakni sesungguhnya mereka (sekali-kali tidak akan dibangkitkan. Katakanlah, \"Memang demi Rabbku, benar-benar kalian akan dibangkitkan, kemudian akan diberitakan kepada kalian apa yang telah kalian kerjakan.\" Yang demikian itu adalah mudah bagi Allah).",[["زَعَمَ","Tuntutan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَن","bahawa"],["لَّن","tidak pernah"],["يُبْعَثُوا۟ ۚ","adakah mereka akan dibangkitkan"],["قُلْ","Katakanlah"],["بَلَىٰ","ya"],["وَرَبِّى","oleh Tuhanku"],["لَتُبْعَثُنَّ","nescaya kamu akan dibangkitkan"],["ثُمَّ","kemudian"],["لَتُنَبَّؤُنَّ","pasti kamu akan dimaklumkan"],["بِمَا","tentang apa"],["عَمِلْتُمْ ۚ","kamu buat"],["وَذَٰلِكَ","Dan bahawa"],["عَلَى","bagi"],["ٱللَّهِ","Allah"],["يَسِيرٌۭ","(adalah) mudah"]]],"5207":["(Maka berimanlah kalian kepada Allah dan Rasul-Nya dan cahaya) yakni Alquran (yang telah Kami turunkan. Dan Allah Maha Mengetahui apa yang kalian kerjakan).",[["فَـَٔامِنُوا۟","Jadi percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَٱلنُّورِ","dan Cahaya"],["ٱلَّذِىٓ","yang"],["أَنزَلْنَا ۚ","Kami telah menurunkan"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"5208":["Ingatlah (hari yang di waktu itu Allah mengumpulkan kalian pada hari pengumpulan) yakni hari kiamat (itulah hari ditampakkannya kesalahan-kesalahan) maksudnya orang-orang mukmin pada hari itu memperoleh keuntungan yang besar dari orang-orang kafir, karena orang-orang mukmin mengambil tempat-tempat tinggal dan istri-istri mereka di surga, seandainya mereka beriman. (Dan barang siapa yang beriman kepada Allah dan mengerjakan amal saleh niscaya Allah akan menutupi kesalahan-kesalahannya dan memasukkannya) menurut suatu qiraat lafal yukaffir dan yudkhilhu dibaca nukaffir dan nudkhilhu (ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Itulah keberuntungan yang besar).",[["يَوْمَ","(The) Hari"],["يَجْمَعُكُمْ","Dia akan mengumpulkan kamu"],["لِيَوْمِ","untuk (hari) itu"],["ٱلْجَمْعِ ۖ","(dari) Perhimpunan"],["ذَٰلِكَ","bahawa"],["يَوْمُ","(akan menjadi) Hari"],["ٱلتَّغَابُنِ ۗ","(daripada) kerugian dan keuntungan bersama"],["وَمَن","Dan sesiapa"],["يُؤْمِنۢ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَيَعْمَلْ","dan melakukan"],["صَـٰلِحًۭا","amal soleh"],["يُكَفِّرْ","Dia akan keluarkan"],["عَنْهُ","daripada dia"],["سَيِّـَٔاتِهِۦ","perbuatan jahatnya"],["وَيُدْخِلْهُ","dan Dia akan menerimanya"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","berkekalan"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۚ","selama-lamanya"],["ذَٰلِكَ","Itu"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","yang hebat"]]],"5209":["(Dan orang-orang yang kafir mendustakan ayat-ayat Kami) yakni Alquran (mereka itulah penghuni-penghuni neraka. Dan itulah seburuk-buruk tempat kembali) yakni neraka itu.",[["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan dinafikan"],["بِـَٔايَـٰتِنَآ","[dalam] Ayat Kami"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ","(dari) api"],["خَـٰلِدِينَ","kekal selama-lamanya"],["فِيهَا ۖ","di dalamnya"],["وَبِئْسَ","Dan celaka adalah"],["ٱلْمَصِيرُ","destinasi"]]],"5210":["(Tidak ada sesuatu musibah pun yang menimpa seseorang kecuali dengan izin Allah) atau dengan kepastian-Nya. (Dan barang siapa yang beriman kepada Allah) melalui ucapannya, bahwa musibah itu datang atas kepastian dari-Nya (niscaya Dia akan memberi petunjuk kepada kalbunya) untuk bersabar di dalam menghadapinya. (Dan Allah Maha Mengetahui segala sesuatu).",[["مَآ","Tidak"],["أَصَابَ","mogok"],["مِن","sebarang"],["مُّصِيبَةٍ","bencana"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin (yang)"],["ٱللَّهِ ۗ","(milik) Allah"],["وَمَن","Dan sesiapa"],["يُؤْمِنۢ","beriman"],["بِٱللَّهِ","kepada Allah"],["يَهْدِ","Dia membimbing"],["قَلْبَهُۥ ۚ","hatinya"],["وَٱللَّهُ","Dan Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","(adalah) Maha Mengetahui"]]],"5211":["(Dan taatlah kepada Allah dan taatlah kepada Rasul, jika kalian berpaling maka sesungguhnya kewajiban rasul Kami hanyalah menyampaikan, amanat Allah, dengan terang) yakni secara jelas.",[["وَأَطِيعُوا۟","Jadi taatlah"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","dan taat"],["ٱلرَّسُولَ ۚ","Rasul"],["فَإِن","tetapi jika"],["تَوَلَّيْتُمْ","kamu berpaling"],["فَإِنَّمَا","kemudian sahaja"],["عَلَىٰ","ke atas"],["رَسُولِنَا","Rasul kami"],["ٱلْبَلَـٰغُ","(ialah) pengangkutan"],["ٱلْمُبِينُ","yang nyata"]]],"5212":["(Dialah Allah, tidak ada Tuhan selain Dia. Dan hendaklah orang-orang mukmin bertawakal kepada Allah saja).",[["ٱللَّهُ","Allah"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۚ","Dia"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","hendaklah meletakkan amanah (mereka)."],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"5213":["(Hai orang-orang yang beriman! Sesungguhnya di antara istri-istri kalian dan anak-anak kalian ada yang menjadi musuh bagi kalian, maka berhati-hatilah kalian) janganlah kalian menaati mereka sehingga menyebabkan kalian ketinggalan tidak mau melakukan perbuatan yang baik, seperti berjihad dan berhijrah. Karena sesungguhnya latar belakang turunnya ayat ini adalah karena menaatinya (dan jika kalian meaafkan) mereka yang telah memperlambat kalian untuk melakukan perbuatan-perbuatan yang baik, karena alasan bahwa mereka merasa berat berpisah dengan kalian (dan tidak memarahi serta mengampuni, mereka, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["ءَامَنُوٓا۟","beriman"],["إِنَّ","Sesungguhnya"],["مِنْ","daripada"],["أَزْوَٰجِكُمْ","pasangan kamu"],["وَأَوْلَـٰدِكُمْ","dan anak-anak kamu"],["عَدُوًّۭا","(adalah) musuh"],["لَّكُمْ","kepada kamu"],["فَٱحْذَرُوهُمْ ۚ","jadi berhati-hatilah dengan mereka"],["وَإِن","Tetapi jika"],["تَعْفُوا۟","kamu maafkan"],["وَتَصْفَحُوا۟","dan terlepas pandang"],["وَتَغْفِرُوا۟","dan memaafkan"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"5214":["(Sesungguhnya harta kalian dan anak-anak kalian hanyalah cobaan) bagi kalian yang melupakan kalian dari perkara-perkara akhirat (dan di sisi Allah lah pahala yang besar) maka janganlah kalian lewatkan hal ini, karena kalian sibuk dengan harta benda dan anak-anak kalian.",[["إِنَّمَآ","Hanya"],["أَمْوَٰلُكُمْ","kekayaan kamu"],["وَأَوْلَـٰدُكُمْ","dan anak-anak kamu"],["فِتْنَةٌۭ ۚ","(adalah) percubaan"],["وَٱللَّهُ","dan Allah"],["عِندَهُۥٓ","dengan Dia"],["أَجْرٌ","(adalah) ganjaran"],["عَظِيمٌۭ","yang besar"]]],"5215":["(Maka bertakwalah kalian kepada Allah menurut kesanggupan kalian) ayat ini memansukh firman-Nya, \"Bertakwalah kepada Allah sebenar-benar takwa kepada-Nya.\" (Q.S. Ali Imran 102) (dan dengarlah) apa yang telah diperintahkan kepada kalian, dengan pendengaran yang dibarengi dengan rasa menerima apa yang kalian dengar (serta taatlah) kepada Allah (dan nafkahkanlah) di jalan ketaatan (nafkah yang baik untuk diri kalian) lafal khairan berkedudukan menjadi khabar dari lafal yakun yang keberadaannya diperkirakan, dan sekaligus menjadi jawab dari amar, yakni niscaya pahalanya buat diri kalian sendiri. (Dan barang siapa yang dipelihara dari kekikiran dirinya, maka mereka itulah orang-orang yang beruntung) orang-orang yang memperoleh keberuntungan.",[["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["مَا","apa"],["ٱسْتَطَعْتُمْ","kamu mampu"],["وَٱسْمَعُوا۟","dan dengar"],["وَأَطِيعُوا۟","dan taat"],["وَأَنفِقُوا۟","dan berbelanja"],["خَيْرًۭا","(ia adalah) lebih baik"],["لِّأَنفُسِكُمْ ۗ","untuk diri kamu sendiri"],["وَمَن","Dan sesiapa"],["يُوقَ","disimpan"],["شُحَّ","(daripada) ketamakan"],["نَفْسِهِۦ","(dari) jiwanya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْمُفْلِحُونَ","(adalah) orang-orang yang berjaya"]]],"5216":["(Jika kalian meminjamkan kepada Allah pinjaman yang baik) seumpamanya kalian mengeluarkan sedekah dengan hati yang tulus ikhlas (niscaya Allah melipatgandakannya kepada kalian) menurut suatu qiraat dibaca yudha``afhu lakum. Dilipatgandakan pembalasannya mulai dari sepuluh kali lipat hingga sampai tujuh ratus kali lipat, dan bahkan lebih dari itu (dan mengampuni kalian) apa yang dikehendaki-Nya. (Dan Allah Maha Pembalas jasa) artinya selalu memberikan balasan amal ketaatan (lagi Maha Penyantun) dalam siksaan-Nya terhadap perbuatan maksiat.",[["إِن","Jika"],["تُقْرِضُوا۟","kamu pinjaman"],["ٱللَّهَ","(kepada) Allah"],["قَرْضًا","pinjaman"],["حَسَنًۭا","dengan baik"],["يُضَـٰعِفْهُ","Dia akan memperbanyakkannya"],["لَكُمْ","bagi kamu"],["وَيَغْفِرْ","dan akan memaafkan"],["لَكُمْ ۚ","kamu"],["وَٱللَّهُ","Dan Allah"],["شَكُورٌ","(adalah) Amat Menghargai"],["حَلِيمٌ","Maha Penyabar"]]],"5217":["(Yang Mengetahui yang gaib) yang tersembunyi (dan yang nyata) yang terang-terangan (Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan dan tindakan-Nya.",[["عَـٰلِمُ","(Yang) Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang disaksikan"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5218":["(Hai Nabi!) makna yang dimaksud ialah umatnya, pengertian ini disimpulkan dari ayat selanjutnya. Atau makna yang dimaksud ialah, katakanlah kepada mereka (apabila kalian menceraikan istri-istri kalian) apabila kalian hendak menjatuhkan talak kepada mereka (maka hendaklah kalian ceraikan mereka pada waktu mereka menghadapi idahnya) yaitu pada permulaan idah, seumpamanya kamu menjatuhkan talak kepadanya sewaktu ia dalam keadaan suci dan kamu belum menggaulinya. Pengertian ini berdasarkan penafsiran dari Rasulullah saw. sendiri menyangkut masalah ini; demikianlah menurut hadis yang telah diriwayatkan oleh Bukhari dan Muslim (dan hitunglah waktu idahnya) artinya jagalah waktu idahnya supaya kalian dapat merujukinya sebelum waktu idah itu habis (serta bertakwalah kepada Allah Rabb kalian) taatlah kalian kepada perintah-Nya dan larangan-Nya. (Janganlah kalian keluarkan mereka dari rumah mereka dan janganlah mereka diizinkan keluar) dari rumahnya sebelum idahnya habis (kecuali kalau mereka mengerjakan perbuatan keji) yakni zina (yang terang) dapat dibaca mubayyinah, artinya terang, juga dapat dibaca mubayyanah, artinya dapat dibuktikan. Maka bila ia melakukan hal tersebut dengan dapat dibuktikan atau ia melakukannya secara jelas, maka ia harus dikeluarkan untuk menjalani hukuman hudud. (Itulah) yakni hal-hal yang telah disebutkan itu (hukum-hukum Allah dan barang siapa yang melanggar hukum-hukum Allah, maka sesungguhnya dia telah berbuat aniaya terhadap dirinya sendiri. Kamu tidak mengetahui barangkali Allah mengadakan sesudah itu) sesudah perceraian itu (sesuatu hal yang baru) yaitu rujuk kembali dengan istri yang telah dicerainya, jika talak yang dijatuhkannya itu baru sekali atau dua kali.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّبِىُّ","Nabi"],["إِذَا","Apabila"],["طَلَّقْتُمُ","kamu cerai"],["ٱلنِّسَآءَ","[para] wanita"],["فَطَلِّقُوهُنَّ","kemudian ceraikan mereka"],["لِعِدَّتِهِنَّ","untuk tempoh menunggu mereka"],["وَأَحْصُوا۟","dan terus mengira"],["ٱلْعِدَّةَ ۖ","(dari) tempoh menunggu"],["وَٱتَّقُوا۟","dan ketakutan"],["ٱللَّهَ","Allah"],["رَبَّكُمْ ۖ","Tuhanmu"],["لَا","Jangan"],["تُخْرِجُوهُنَّ","mengusir mereka"],["مِنۢ","daripada"],["بُيُوتِهِنَّ","rumah mereka"],["وَلَا","dan bukan"],["يَخْرُجْنَ","mereka harus pergi"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَأْتِينَ","mereka komited"],["بِفَـٰحِشَةٍۢ","suatu maksiat"],["مُّبَيِّنَةٍۢ ۚ","yang nyata"],["وَتِلْكَ","Dan ini"],["حُدُودُ","(adalah) had"],["ٱللَّهِ ۚ","(milik) Allah"],["وَمَن","Dan sesiapa"],["يَتَعَدَّ","melanggar"],["حُدُودَ","(the) had"],["ٱللَّهِ","(milik) Allah"],["فَقَدْ","maka sudah tentu"],["ظَلَمَ","dia telah melakukan kesalahan"],["نَفْسَهُۥ ۚ","dirinya sendiri"],["لَا","Tidak"],["تَدْرِى","kamu tahu"],["لَعَلَّ","barangkali"],["ٱللَّهَ","Allah"],["يُحْدِثُ","akan membawa"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["أَمْرًۭا","sesuatu perkara"]]],"5219":["(Apabila mereka telah mendekati akhir idahnya) atau masa idah mereka hampir habis (maka tahanlah mereka) seumpamanya kalian rujuk dengan mereka (dengan baik) artinya tidak memudaratkan kepada mereka (atau lepaskanlah mereka dengan baik) biarkanlah mereka menyelesaikan idahnya dan janganlah kamu menjatuhkan kemudaratan terhadap mereka melalui rujuk (dan persaksikanlah dengan dua orang saksi yang adil di antara kalian) dalam masalah rujuk atau talak ini (dan hendaklah kalian tegakkan kesaksian itu karena Allah) bukan karena demi rang yang dipersaksikan atau bukan karena demi rujuk atau talaknya. (Demikianlah diberi pengajaran dengan itu orang yang beriman kepada Allah dan hari akhirat. Barang siapa yang bertakwa kepada Allah niscaya Dia akan mengadakan baginya jalan keluar) dari malapetaka di dunia dan di akhirat.",[["فَإِذَا","Kemudian apabila"],["بَلَغْنَ","mereka telah sampai"],["أَجَلَهُنَّ","istilah mereka"],["فَأَمْسِكُوهُنَّ","kemudian mengekalkan mereka"],["بِمَعْرُوفٍ","dengan kebaikan"],["أَوْ","atau"],["فَارِقُوهُنَّ","berpisah dengan mereka"],["بِمَعْرُوفٍۢ","dengan kebaikan"],["وَأَشْهِدُوا۟","Dan ambil saksi"],["ذَوَىْ","dua orang lelaki"],["عَدْلٍۢ","cuma"],["مِّنكُمْ","antara kamu"],["وَأَقِيمُوا۟","dan menubuhkan"],["ٱلشَّهَـٰدَةَ","kesaksian"],["لِلَّهِ ۚ","kerana Allah"],["ذَٰلِكُمْ","Itu"],["يُوعَظُ","diarahkan"],["بِهِۦ","dengannya"],["مَن","sesiapa sahaja"],["كَانَ","[adalah]"],["يُؤْمِنُ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ ۚ","yang Terakhir"],["وَمَن","Dan sesiapa"],["يَتَّقِ","ketakutan"],["ٱللَّهَ","Allah"],["يَجْعَل","Dia akan buat"],["لَّهُۥ","baginya"],["مَخْرَجًۭا","jalan keluar"]]],"5220":["(Dan memberinya rezeki dari arah yang tiada disangka-sangkanya) dari arah yang belum pernah terbisik dalam kalbunya. (Dan barang siapa yang bertawakal kepada Allah) dalam semua perkaranya (niscaya Allah akan memberi kecukupan) akan mencukupinya. (Sesungguhnya Allah melaksanakan urusan-Nya) tentang apa yang dikehendaki-Nya. Menurut suatu qiraat dibaca baalighu amrihi yakni dengan dimudhafkan. (Sesungguhnya Allah telah menjadikan bagi setiap sesuatu) seperti hidup penuh dengan kecukupan, dan hidup sengsara (ketentuan) atau waktu-waktu yang ditentukan.",[["وَيَرْزُقْهُ","Dan Dia akan memberinya rezeki"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["يَحْتَسِبُ ۚ","dia fikir"],["وَمَن","Dan sesiapa"],["يَتَوَكَّلْ","meletakkan kepercayaannya"],["عَلَى","ke atas"],["ٱللَّهِ","Allah"],["فَهُوَ","kemudian Dia"],["حَسْبُهُۥٓ ۚ","(adalah) mencukupi baginya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بَـٰلِغُ","(akan) capai"],["أَمْرِهِۦ ۚ","tujuan dia"],["قَدْ","Sesungguhnya"],["جَعَلَ","telah ditetapkan"],["ٱللَّهُ","Allah"],["لِكُلِّ","untuk setiap"],["شَىْءٍۢ","perkara"],["قَدْرًۭا","satu ukuran"]]],"5221":["(Dan perempuan-perempuan) dibaca wallaa'iy dan wallaa'i, dengan memakai hamzah dan ya atau tanpa memakai ya, demikian pula lafal yang sama sesudahnya (yang putus asa dari haid) lafal al-mahidh di sini bermakna haid (di antara perempuan-perempuan kalian jika kalian ragu-ragu) tentang masa idahnya (maka idah mereka adalah tiga bulan; dan begitu pula perempuan-perempuan yang tidak haid) karena mengingat mereka masih di bawah umur, maka idah mereka tiga bulan pula. Kedua kasus ini menyangkut wanita-wanita atau istri-istri yang tidak ditinggal mati oleh suaminya. Adapun istri-istri yang ditinggal mati oleh suaminya, idah mereka sebagaimana yang disebutkan di dalam firman-Nya berikut ini, yaitu, \"Hendaklah para istri itu menangguhkan dirinya (beridah) empat bulan sepuluh hari.\" (Q.S. Al-Baqarah 234) (Dan perempuan-perempuan yang hamil masa idahnya) baik mereka itu karena ditalak atau karena ditinggal mati oleh suaminya, maka batas masa idah mereka ialah (sampai mereka melahirkan kandungannya. Dan barang siapa yang bertakwa kepada Allah niscaya Allah menjadikan baginya kemudahan dalam urusannya) baik di dunia maupun di akhirat.",[["وَٱلَّـٰٓـِٔى","Dan orang yang"],["يَئِسْنَ","sudah putus asa"],["مِنَ","daripada"],["ٱلْمَحِيضِ","haid itu"],["مِن","antara"],["نِّسَآئِكُمْ","wanita kamu"],["إِنِ","jika"],["ٱرْتَبْتُمْ","kamu ragu-ragu"],["فَعِدَّتُهُنَّ","kemudian tempoh menunggu mereka"],["ثَلَـٰثَةُ","(adalah) tiga"],["أَشْهُرٍۢ","bulan"],["وَٱلَّـٰٓـِٔى","dan mereka yang"],["لَمْ","tidak"],["يَحِضْنَ ۚ","[mereka] datang haid"],["وَأُو۟لَـٰتُ","Dan mereka yang (ada)"],["ٱلْأَحْمَالِ","mengandung"],["أَجَلُهُنَّ","istilah mereka"],["أَن","sehingga"],["يَضَعْنَ","mereka menyampaikan"],["حَمْلَهُنَّ ۚ","bebanan mereka"],["وَمَن","Dan sesiapa"],["يَتَّقِ","ketakutan"],["ٱللَّهَ","Allah"],["يَجْعَل","Dia akan buat"],["لَّهُۥ","baginya"],["مِنْ","daripada"],["أَمْرِهِۦ","urusan dia"],["يُسْرًۭا","memudahkan"]]],"5222":["(Itulah) yaitu hal-hal yang menyangkut masalah idah adalah (perintah Allah) atau hukum-Nya (yang diturunkan-Nya kepada kalian; dan barang siapa yang bertakwa kepada Allah niscaya Dia akan menutupi kesalahan-kesalahannya dan akan melipatgandakan pahala baginya).",[["ذَٰلِكَ","Itu"],["أَمْرُ","(ialah) Perintah"],["ٱللَّهِ","(milik) Allah"],["أَنزَلَهُۥٓ","yang telah diturunkan-Nya"],["إِلَيْكُمْ ۚ","kepada kamu"],["وَمَن","dan sesiapa"],["يَتَّقِ","ketakutan"],["ٱللَّهَ","Allah"],["يُكَفِّرْ","Dia akan keluarkan"],["عَنْهُ","daripada dia"],["سَيِّـَٔاتِهِۦ","perbuatan jahatnya"],["وَيُعْظِمْ","dan buat hebat"],["لَهُۥٓ","baginya"],["أَجْرًا","pahalanya"]]],"5223":["(Tempatkanlah mereka) yakni istri-istri yang ditalak itu (pada tempat kalian tinggal) pada sebagian tempat-tempat tinggal kalian (menurut kemampuan kalian) sesuai dengan kemampuan kalian, lafal ayat ini menjadi athaf bayan atau badal dari lafal yang sebelumnya dengan mengulangi penyebutan huruf jarr-nya/kata depan dan memperkirakan adanya mudhaf. Yakni pada tempat-tempat tinggal yang kalian mampui, bukannya pada tempat-tempat tinggal yang di bawah itu (dan janganlah kalian menyusahkan mereka untuk menyempitkan hati mereka) dengan memberikan kepada mereka tempat-tempat tinggal yang tidak layak, sehingga mereka terpaksa butuh untuk keluar atau membutuhkan nafkah, lalu karena itu maka mereka mengeluarkan biaya sendiri. (Dan jika mereka itu sedang hamil, maka berikanlah kepada mereka nafkahnya hingga mereka bersalin, kemudian jika mereka menyusukan bayi kalian) maksudnya menyusukan anak-anak kalian hasil hubungan dengan mereka (maka berikanlah kepada mereka upahnya) sebagai upah menyusukan (dan bermusyawarahlah di antara kalian) antara kalian dan mereka (dengan baik) dengan cara yang baik menyangkut hak anak-anak kalian, yaitu melalui permusyawaratan sehingga tercapailah kesepakatan mengenai upah menyusukan (dan jika kalian menemui kesulitan) artinya kalian enggan untuk menyusukannya; yaitu dari pihak ayah menyangkut masalah upah, sedangkan dari pihak ibu, siapakah yang akan menyusukannya (maka boleh menyusukan bayinya) maksudnya menyusukan si anak itu semata-mata demi ayahnya (wanita yang lain) dan ibu si anak itu tidak boleh dipaksa untuk menyusukannya.",[["أَسْكِنُوهُنَّ","Tinggalkan mereka"],["مِنْ","daripada"],["حَيْثُ","di mana"],["سَكَنتُم","kamu tinggal"],["مِّن","(keluar) daripada"],["وُجْدِكُمْ","kemampuan kamu"],["وَلَا","dan jangan"],["تُضَآرُّوهُنَّ","membahayakan mereka"],["لِتُضَيِّقُوا۟","kepada kesusahan"],["عَلَيْهِنَّ ۚ","[pada] mereka"],["وَإِن","Dan jika"],["كُنَّ","mereka adalah"],["أُو۟لَـٰتِ","mereka (yang)"],["حَمْلٍۢ","mengandung"],["فَأَنفِقُوا۟","kemudian habiskan"],["عَلَيْهِنَّ","ke atas mereka"],["حَتَّىٰ","sehingga"],["يَضَعْنَ","mereka menyampaikan"],["حَمْلَهُنَّ ۚ","beban mereka"],["فَإِنْ","Kemudian jika"],["أَرْضَعْنَ","mereka menyusu"],["لَكُمْ","bagi kamu"],["فَـَٔاتُوهُنَّ","kemudian berikan mereka"],["أُجُورَهُنَّ ۖ","bayaran mereka"],["وَأْتَمِرُوا۟","dan berunding"],["بَيْنَكُم","antara kamu sendiri"],["بِمَعْرُوفٍۢ ۖ","dengan kebaikan"],["وَإِن","tetapi jika"],["تَعَاسَرْتُمْ","kamu tidak bersetuju"],["فَسَتُرْضِعُ","kemudian boleh menyusu"],["لَهُۥٓ","baginya"],["أُخْرَىٰ","seorang lagi (wanita)"]]],"5224":["(Hendaklah memberikan nafkah) kepada istri-istri yang telah ditalak, dan kepada istri-istri yang sedang menyusukan (orang yang mampu menurut kemampuannya. Dan orang yang dibatasi) disempitkan (rezekinya hendaklah memberi nafkah dari apa yang didatangkan kepadanya) yaitu dari rezeki yang telah diberikan kepadanya (oleh Allah) sesuai dengan kemampuannya. (Allah tidak memikulkan beban kepada seseorang melainkan sekedar apa yang Allah berikan kepadanya. Allah kelak akan memberikan kelapangan sesudah kesempitan) dan ternyata Allah memberikan kelapangan itu melalui kemenangan-kemenangan yang dialami oleh kaum muslimin.",[["لِيُنفِقْ","Biar berbelanja"],["ذُو","pemilik"],["سَعَةٍۢ","(daripada) cara yang mencukupi"],["مِّن","daripada"],["سَعَتِهِۦ ۖ","maksudnya yang cukup"],["وَمَن","dan (dia) siapa"],["قُدِرَ","adalah terhad"],["عَلَيْهِ","pada dia"],["رِزْقُهُۥ","rezekinya"],["فَلْيُنفِقْ","biar dia belanja"],["مِمَّآ","daripada apa"],["ءَاتَىٰهُ","dia telah diberi"],["ٱللَّهُ ۚ","(oleh) Allah"],["لَا","tidak"],["يُكَلِّفُ","bebanan"],["ٱللَّهُ","Allah"],["نَفْسًا","mana-mana jiwa"],["إِلَّا","kecuali"],["مَآ","(dengan) apa"],["ءَاتَىٰهَا ۚ","Dia telah memberikannya"],["سَيَجْعَلُ","Akan membawa"],["ٱللَّهُ","Allah"],["بَعْدَ","selepas"],["عُسْرٍۢ","kesusahan"],["يُسْرًۭا","memudahkan"]]],"5225":["(Dan berapalah banyaknya) lafal ka'ayyin huruf kafnya adalah huruf jarr, masuk ke dalam huruf ayy yang bermakna kam. Sudah berapa banyak (negeri) yakni banyak negeri-negeri (yang mendurhakai) yang penduduknya telah berbuat durhaka (perintah Rabbnya dan rasul-rasul-Nya, maka Kami hisab penduduk negeri-negeri itu) di akhirat, sekalipun hari akhirat itu belum datang. Diungkapkan dengan memakai fi'il madhi, yaitu haasabnaahaa, karena hal itu pasti terjadi (dengan hisab yang keras, dan Kami azab mereka dengan azab yang mengerikan) dapat dibaca nukra dan nukura, artinya azab yang mengerikan, yaitu azab neraka.",[["وَكَأَيِّن","Dan berapa banyak"],["مِّن","daripada"],["قَرْيَةٍ","sebuah bandar"],["عَتَتْ","memberontak"],["عَنْ","terhadap"],["أَمْرِ","(the) Perintah"],["رَبِّهَا","(dari) Tuhannya"],["وَرُسُلِهِۦ","dan Rasul-rasulNya"],["فَحَاسَبْنَـٰهَا","jadi Kami mengambil kiranya"],["حِسَابًۭا","sebuah akaun"],["شَدِيدًۭا","teruk"],["وَعَذَّبْنَـٰهَا","dan Kami menghukumnya"],["عَذَابًۭا","azab"],["نُّكْرًۭا","dahsyat"]]],"5226":["(Maka mereka merasakan akibat dari perbuatannya) hukuman dari perbuatannya (dan adalah akibat perbuatan mereka kerugian yang besar) kerugian dan kebinasaan.",[["فَذَاقَتْ","Jadi rasanya"],["وَبَالَ","(buruk) akibatnya"],["أَمْرِهَا","(dari) urusannya"],["وَكَانَ","dan adalah"],["عَـٰقِبَةُ","(akhirnya)."],["أَمْرِهَا","(dari) urusannya"],["خُسْرًا","kerugian"]]],"5227":["(Allah menyediakan bagi mereka azab yang keras) di sini ancaman tersebut diulangi untuk mengukuhkan makna (maka bertakwalah kepada Allah, hai orang-orang yang mempunyai akal) pikiran (yaitu orang-orang yang beriman) lafal alladziina aamanuu merupakan sifat bagi munada atau orang-orang yang diseru tadi atau merupakan bayan atau penjelasan baginya. (Sesungguhnya Allah telah menurunkan peringatan kepada kalian) yakni Alquran.",[["أَعَدَّ","Telah menyediakan"],["ٱللَّهُ","Allah"],["لَهُمْ","bagi mereka"],["عَذَابًۭا","azab"],["شَدِيدًۭا ۖ","teruk"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["يَـٰٓأُو۟لِى","Wahai lelaki"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟ ۚ","telah beriman"],["قَدْ","Sesungguhnya"],["أَنزَلَ","Telah menurunkan"],["ٱللَّهُ","Allah"],["إِلَيْكُمْ","kepada kamu"],["ذِكْرًۭا","sebuah Mesej"]]],"5228":["(Dan mengutus seorang rasul) yakni Nabi Muhammad saw. Dinashabkan oleh fi'il yang diperkirakan keberadaannya yakni Allah mengutus seorang rasul (yang membacakan kepada kalian ayat-ayat Allah yang menerangkan) dapat dibaca mubayyanatun, artinya yang menerangkan, juga dapat dibaca mubayyinatun, artinya yang terang; penafsirannya sebagaimana yang telah lalu (supaya Dia mengeluarkan orang-orang yang beriman dan mengerjakan amal-amal saleh) sesudah datangnya peringatan atau Alquran dan rasul (dari kegelapan) dari kekafiran yang mereka bergelimang di dalamnya (kepada cahaya) kepada iman yang menegakkan mereka sesudah mereka kafir. (Dan barang siapa beriman kepada Allah dan mengerjakan amal saleh niscaya Dia akan memasukkannya) menurut suatu qiraat lafal yudkhilhu dibaca nudkhilhu, artinya niscaya Kami akan memasukkannya (ke dalam surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Sesungguhnya Allah memberikan rezeki yang baik kepadanya) yaitu rezeki surga yang kenikmatannya tiada henti-hentinya.",[["رَّسُولًۭا","Seorang Rasul"],["يَتْلُوا۟","mengaji"],["عَلَيْكُمْ","kepada kamu"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["مُبَيِّنَـٰتٍۢ","yang nyata"],["لِّيُخْرِجَ","supaya dia boleh bawa keluar"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["مِنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["إِلَى","ke arah"],["ٱلنُّورِ ۚ","cahaya itu"],["وَمَن","Dan sesiapa"],["يُؤْمِنۢ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَيَعْمَلْ","dan melakukan"],["صَـٰلِحًۭا","amal soleh"],["يُدْخِلْهُ","Dia akan mengakuinya"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","berkekalan"],["فِيهَآ","di dalamnya"],["أَبَدًۭا ۖ","selama-lamanya"],["قَدْ","Sesungguhnya"],["أَحْسَنَ","Telah (diberikan) baik"],["ٱللَّهُ","(oleh) Allah"],["لَهُۥ","baginya"],["رِزْقًا","peruntukan"]]],"5229":["(Allah-lah yang menciptakan tujuh langit dan seperti itu pula bumi) tujuh lapis bumi. (Turunlah perintah) wahyu-Nya (di antaranya) di antara langit dan bumi, malaikat Jibril turun dari langit yang ketujuh hingga ke bumi lapis tujuh (agar kalian mengetahui) lafal lita'lamuu bertaalluq kepada lafal yang tidak disebutkan, yakni Allah memberi tahu kepada kalian akan hal tersebut, yaitu mengenai masalah penciptaan dan penurunan wahyu-Nya (bahwasanya Allah Maha Kuasa atas segala sesuatu, dan sesungguhnya Allah ilmu-Nya benar-benar meliputi segala sesuatu).",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Dia Yang"],["خَلَقَ","dicipta"],["سَبْعَ","tujuh"],["سَمَـٰوَٰتٍۢ","syurga"],["وَمِنَ","dan daripada"],["ٱلْأَرْضِ","bumi"],["مِثْلَهُنَّ","(yang) seperti mereka"],["يَتَنَزَّلُ","Turun"],["ٱلْأَمْرُ","perintah itu"],["بَيْنَهُنَّ","antara mereka"],["لِتَعْلَمُوٓا۟","supaya kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"],["وَأَنَّ","Dan bahawa"],["ٱللَّهَ","Allah"],["قَدْ","sesungguhnya"],["أَحَاطَ","merangkumi"],["بِكُلِّ","semua"],["شَىْءٍ","benda"],["عِلْمًۢا","(dalam) pengetahuan"]]],"5230":["(Hai nabi! Mengapa kamu mengharamkan apa yang Allah menghalalkannya bagimu) mengenai istri budak wanitamu, yakni Mariyah Qibtiah; yaitu sewaktu Nabi saw. menggaulinya di rumah Hafshah, sedangkan pada waktu itu Siti Hafshah sedang tidak ada di rumah. Lalu datanglah Siti Hafshah, dan ia merasa keberatan dengan adanya hal tersebut yang dilakukan oleh Nabi saw. di dalam rumahnya dan di tempat tidurnya. Lalu kamu mengatakan, dia (Siti Mariyah) haram atas diriku (kamu mencari) dengan mengharamkannya atas dirimu (keridaan istri-istrimu) kerelaan mereka terhadap dirimu. (Dan Allah Maha Pengampun lagi Maha Penyayang) Dia telah mengampunimu atas tindakan pengharamanmu itu.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّبِىُّ","Nabi"],["لِمَ","kenapa (buat)"],["تُحَرِّمُ","kamu melarang"],["مَآ","apa"],["أَحَلَّ","telah menghalalkan"],["ٱللَّهُ","Allah"],["لَكَ ۖ","bagi kamu"],["تَبْتَغِى","mencari"],["مَرْضَاتَ","(untuk) tolong"],["أَزْوَٰجِكَ ۚ","isteri-isteri kamu"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"5231":["(Sesungguhnya Allah telah mewajibkan) telah mensyariatkan (kepada kamu sekalian membebaskan diri dari sumpah kalian) artinya kalian melepaskan diri dari sumpah yang telah kalian katakan dengan cara membayar kifarat sebagaimana yang telah disebutkan di dalam surat Al-Maidah. Dan termasuk di antara sumpah-sumpah itu ialah mengharamkan budak wanita. Apakah Nabi saw. membayar kifarat? Muqatil mengatakan, bahwa Nabi saw. telah memerdekakan seorang budak sebagai kifaratnya yang telah mengharamkan Siti Mariyah atas dirinya. Akan tetapi Hasan mengatakan, bahwa Nabi saw. tidak membayar kifarat, karena sesungguhnya ia telah mendapat ampunan dari Allah (dan Allah adalah Pelindung kalian) yang menolong kalian (dan Dia Maha Mengetahui lagi Maha Bijaksana).",[["قَدْ","Sesungguhnya"],["فَرَضَ","telah ditahbiskan"],["ٱللَّهُ","Allah"],["لَكُمْ","bagi kamu"],["تَحِلَّةَ","(the) pembubaran"],["أَيْمَـٰنِكُمْ ۚ","(dari) sumpah kamu"],["وَٱللَّهُ","Dan Allah"],["مَوْلَىٰكُمْ ۖ","(ialah) Pelindungmu"],["وَهُوَ","dan Dia"],["ٱلْعَلِيمُ","(ialah) Yang Maha Mengetahui"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"5232":["(Dan) ingatlah (ketika Nabi membicarakan secara rahasia kepada salah seorang dari istri-istrinya) yakni kepada Siti Hafshah (suatu pembicaraan) tentang mengharamkan Siti Mariyah atas dirinya, kemudian Nabi saw. berkata kepada Siti Hafshah, \"Jangan sekali-kali kamu membuka rahasia ini.\" (Maka tatkala menceritakan peristiwa itu) kepada Siti Aisyah, ia menduga bahwa hal ini tidak dosa (dan Allah memberitahukan hal itu) Dia membukanya (kepadanya) yakni kepada Nabi Muhammad tentang pembicaraan Siti Hafshah kepada Siti Aisyah itu (lalu dia memberitahukan sebagiannya) kepada Siti Hafshah (dan menyembunyikan sebagian yang lain) sebagai kemurahan dari dirinya terhadap dia. (Maka tatkala dia, Muhammad, memberitahukan pembicaraan itu, lalu Hafshah bertanya, \"Siapakah yang telah memberitahukan hal ini kepadamu?\" Nabi menjawab, \"Telah diberitahukan kepadaku oleh Yang Maha Mengetahui lagi Maha Waspada\") yakni Allah swt.",[["وَإِذْ","Dan apabila"],["أَسَرَّ","diceritakan"],["ٱلنَّبِىُّ","Nabi"],["إِلَىٰ","kepada"],["بَعْضِ","satu"],["أَزْوَٰجِهِۦ","(dari) isteri-isterinya"],["حَدِيثًۭا","satu kenyataan"],["فَلَمَّا","dan apabila"],["نَبَّأَتْ","dia memaklumkan"],["بِهِۦ","mengenainya"],["وَأَظْهَرَهُ","dan menjadikannya jelas"],["ٱللَّهُ","Allah"],["عَلَيْهِ","kepadanya"],["عَرَّفَ","dia buat tahu"],["بَعْضَهُۥ","sebahagian daripadanya"],["وَأَعْرَضَ","dan dielakkan"],["عَنۢ","[daripada]"],["بَعْضٍۢ ۖ","bahagian"],["فَلَمَّا","Kemudian apabila"],["نَبَّأَهَا","dia memberitahunya"],["بِهِۦ","mengenainya"],["قَالَتْ","katanya"],["مَنْ","Siapa"],["أَنۢبَأَكَ","memberitahu kamu"],["هَـٰذَا ۖ","ini"],["قَالَ","Dia berkata"],["نَبَّأَنِىَ","Telah memaklumkan kepada aku"],["ٱلْعَلِيمُ","yang Maha Mengetahui"],["ٱلْخَبِيرُ","yang Maha Mengetahui"]]],"5233":["(Jika kamu berdua bertobat) yakni Siti Hafshah dan Siti Aisyah (kepada Allah, maka sesungguhnya hati kamu berdua telah condong) cenderung untuk diharamkannya Siti Mariyah, artinya, kamu berdua merahasiakan hal tersebut dalam hati kamu, padahal Nabi saw. tidak menyukai hal tersebut, dan hal ini adalah suatu perbuatan yang berdosa. Jawab Syarat dari kalimat ini tidak disebutkan, yakni jika kamu berdua bertobat kepada Allah, maka tobat kamu diterima. Diungkapkan dengan memakai lafal quluubun dalam bentuk jamak sebagai pengganti dari lafal qalbaini, hal ini tiada lain karena dirasakan amat berat mengucapkan dua isim tatsniah yang digabungkan dalam satu lafal (dan jika kamu berdua saling bantu-membantu) lafal tazhaahara artinya bantu-membantu. Menurut qiraat yang lain dibaca tazhzhaharaa bentuk asalnya adalah Tatazhaaharaa, kemudian huruf ta yang kedua diidgamkan ke dalam huruf zha sehingga jadilah tazhzhaaharaa (terhadapnya) terhadap Nabi saw. dalam melakukan hal-hal yang tidak disukainya, yakni membuat susah Nabi saw. (maka sesungguhnya Allah adalah) lafal huwa ini merupakan dhamir fashl (Pelindungnya) maksudnya, yang menolongnya (dan begitu pula Jibril dan orang-orang mukmin yang saleh) seperti Abu Bakar dan Umar r.a. Lafal ini diathafkan secara mahall kepada isimnya inna, yakni begitu pula mereka akan menjadi penolongnya (dan selain dari itu malaikat-malaikat) yaitu sesudah pertolongan Allah dan orang-orang yang telah disebutkan tadi (adalah penolongnya pula) maksudnya mereka semua menjadi penolong Nabi terhadap kamu berdua.",[["إِن","Jika"],["تَتُوبَآ","kamu berdua berpaling"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["فَقَدْ","jadi memang"],["صَغَتْ","(adalah) cenderung"],["قُلُوبُكُمَا ۖ","hati kamu"],["وَإِن","tetapi jika"],["تَظَـٰهَرَا","kamu sandaran antara satu sama lain"],["عَلَيْهِ","terhadapnya"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["مَوْلَىٰهُ","(adalah) Pelindungnya"],["وَجِبْرِيلُ","dan Jibril"],["وَصَـٰلِحُ","dan (orang-orang) yang soleh"],["ٱلْمُؤْمِنِينَ ۖ","orang yang beriman"],["وَٱلْمَلَـٰٓئِكَةُ","dan para Malaikat"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["ظَهِيرٌ","(adalah) pembantunya"]]],"5234":["(Jika Nabi menceraikan kalian, boleh jadi Rabbnya) maksudnya, jika nabi menceraikan istri-istrinya (akan memberi ganti kepadanya) dapat dibaca yubdilahu dan yubaddilahu (dengan istri-istri yang lebih baik daripada kalian) lafal azwaajan ini menjadi khabar dari lafal 'asaa sedangkan jumlah an yubdilahu dan seterusnya menjadi jawab syarath. Di sini tidak ada badal karena apa yang disebutkan pada syarat tidak terjadi, yakni perceraian itu tidak pernah terjadi (yang patuh) artinya mengakui Islam (yang beriman) yakni ikhlas hatinya kepada Islam (yang taat) mereka taat (yang bertobat, rajin beribadat, rajin berpuasa) yakni gemar melakukan puasa atau yang berhijrah (yang janda dan yang perawan)",[["عَسَىٰ","barangkali"],["رَبُّهُۥٓ","Tuhannya"],["إِن","jika"],["طَلَّقَكُنَّ","dia ceraikan kamu"],["أَن","[bahawa]"],["يُبْدِلَهُۥٓ","Dia akan menggantikannya"],["أَزْوَٰجًا","isteri-isteri"],["خَيْرًۭا","lebih baik"],["مِّنكُنَّ","daripada kamu"],["مُسْلِمَـٰتٍۢ","tunduk"],["مُّؤْمِنَـٰتٍۢ","setia"],["قَـٰنِتَـٰتٍۢ","patuh"],["تَـٰٓئِبَـٰتٍ","bertaubat"],["عَـٰبِدَٰتٍۢ","yang menyembah"],["سَـٰٓئِحَـٰتٍۢ","yang berpuasa"],["ثَيِّبَـٰتٍۢ","sebelum ini berkahwin"],["وَأَبْكَارًۭا","dan anak dara"]]],"5235":["(Hai orang-orang yang beriman! Peliharalah diri kalian dan keluarga kalian) dengan mengarahkan mereka kepada jalan ketaatan kepada Allah (dari api neraka yang bahan bakarnya adalah manusia) orang-orang kafir (dan batu) seperti berhala-berhala yang mereka sembah adalah sebagian dari bahan bakar neraka itu. Atau dengan kata lain api neraka itu sangat panas, sehingga hal-hal tersebut dapat terbakar. Berbeda halnya dengan api di dunia, karena api di dunia dinyalakan dengan kayu dan lain-lainnya (penjaganya malaikat-malaikat) yakni, juru kunci neraka itu adalah malaikat-malaikat yang jumlahnya ada sembilan belas malaikat, sebagaimana yang akan diterangkan nanti dalam surat Al-Muddatstsir (yang kasar) lafal ghilaazhun ini diambil dari asal kata ghilazhul qalbi, yakni kasar hatinya (yang keras) sangat keras hantamannya (mereka tidak pernah mendurhakai Allah terhadap apa yang telah diperintahkan-Nya kepada mereka) lafal maa amarahum berkedudukan sebagai badal dari lafal Allah. Atau dengan kata lain, malaikat-malaikat penjaga neraka itu tidak pernah mendurhakai perintah Allah (dan mereka selalu mengerjakan apa yang diperintahkan) lafaz ayat ini berkedudukan menjadi badal dari lafal yang sebelumnya. Dalam ayat ini terkandung ancaman bagi orang-orang mukmin supaya jangan murtad; dan juga ayat ini merupakan ancaman pula bagi orang-orang munafik yaitu, mereka yang mengaku beriman dengan lisannya tetapi hati mereka masih tetap kafir.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["ءَامَنُوا۟","beriman"],["قُوٓا۟","Lindungi"],["أَنفُسَكُمْ","kamu sendiri"],["وَأَهْلِيكُمْ","dan keluarga kamu"],["نَارًۭا","(dari) api"],["وَقُودُهَا","bahan bakar siapa"],["ٱلنَّاسُ","(adalah) orang"],["وَٱلْحِجَارَةُ","dan batu"],["عَلَيْهَا","atasnya"],["مَلَـٰٓئِكَةٌ","(adalah) Malaikat"],["غِلَاظٌۭ","tegas"],["شِدَادٌۭ","teruk"],["لَّا","tidak"],["يَعْصُونَ","mereka ingkar"],["ٱللَّهَ","Allah"],["مَآ","(dalam) apa"],["أَمَرَهُمْ","Dia memerintahkan mereka"],["وَيَفْعَلُونَ","tetapi mereka lakukan"],["مَا","apa"],["يُؤْمَرُونَ","mereka diperintah"]]],"5236":["(Hai orang-orang kafir, janganlah kalian mengemukakan uzur pada hari ini) ucapan ini dikatakan kepada mereka sewaktu mereka dimasukkan ke dalam neraka; dikatakan demikian karena uzur atau alasan itu tiada gunanya. (Sesungguhnya kalian hanya diberi balasan menurut apa yang kalian kerjakan) sebagai balasannya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) siapa"],["كَفَرُوا۟","kufur"],["لَا","Jangan"],["تَعْتَذِرُوا۟","buat alasan"],["ٱلْيَوْمَ ۖ","hari ini"],["إِنَّمَا","Hanya"],["تُجْزَوْنَ","kamu akan mendapat balasan"],["مَا","(untuk) apa"],["كُنتُمْ","kamu pernah"],["تَعْمَلُونَ","lakukan"]]],"5237":["(Hai orang-orang yang beriman, bertobatlah kepada Allah dengan tobat yang semurni-murninya) dapat dibaca nashuuhaa dan nushuuhaa, artinya tobat yang sebenar-benarnya, bertobat tidak akan mengulangi dosa lagi, dan menyesali apa yang telah dikerjakannya (mudah-mudahan Rabb kalian) lafal 'asaa ini mengandung makna tarajji, yakni sesuatu yang dapat diharapkan akan terjadi (akan menutupi kesalahan-kesalahan kalian, dan memasukkan kalian ke dalam surga-surga) yakni taman-taman surga (yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak menghinakan) Allah tidak akan memasukkan ke dalam neraka (Nabi dan orang-orang yang beriman bersama dia; sedangkan cahaya mereka memancar di hadapan mereka) maksudnya, di depan mereka terang benderang oleh cahayanya (dan) cahaya itu pun memancar pula (di sebelah kanan mereka. Mereka berkata) lafal yaquuluuna merupakan jumlah isti'naf atau kalimat baru: (\"Ya Rabb kami! Sempurnakanlah bagi kami cahaya kami) hingga sampai ke surga, sedangkan orang-orang munafik cahaya mereka padam (dan ampunilah kami) wahai Rabb kami (sesungguhnya Engkau Maha Kuasa atas segala sesuatu.\").",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","(kamu) yang beriman"],["ءَامَنُوا۟","beriman"],["تُوبُوٓا۟","pusing"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["تَوْبَةًۭ","(dalam) taubat"],["نَّصُوحًا","ikhlas"],["عَسَىٰ","barangkali"],["رَبُّكُمْ","Tuhanmu"],["أَن","kehendak"],["يُكَفِّرَ","keluarkan"],["عَنكُمْ","daripada kamu"],["سَيِّـَٔاتِكُمْ","perbuatan jahat kamu"],["وَيُدْخِلَكُمْ","dan mengakui kamu"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["يَوْمَ","(pada) hari"],["لَا","tidak"],["يُخْزِى","akan mendapat kehinaan"],["ٱللَّهُ","(oleh) Allah"],["ٱلنَّبِىَّ","Nabi"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["مَعَهُۥ ۖ","dengan dia"],["نُورُهُمْ","cahaya mereka"],["يَسْعَىٰ","akan berjalan"],["بَيْنَ","sebelum"],["أَيْدِيهِمْ","tangan mereka"],["وَبِأَيْمَـٰنِهِمْ","dan di sebelah kanan mereka"],["يَقُولُونَ","mereka akan berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["أَتْمِمْ","Sempurna"],["لَنَا","bagi kami"],["نُورَنَا","cahaya kita"],["وَٱغْفِرْ","dan memberi keampunan"],["لَنَآ ۖ","kepada kami"],["إِنَّكَ","Sesungguhnya, Engkau"],["عَلَىٰ","(sudah) berakhir"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"5238":["(Hai Nabi! Perangilah orang-orang kafir) dengan memakai senjata (dan orang-orang munafik) dengan memakai lisan dan hujah (dan bersikap keraslah terhadap mereka) dengan berbicara keras dan membenci mereka. (Tempat mereka adalah neraka Jahanam, dan seburuk-buruk tempat kembali itu) adalah neraka Jahanam.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّبِىُّ","Nabi"],["جَـٰهِدِ","Berusahalah"],["ٱلْكُفَّارَ","(terhadap) orang-orang kafir"],["وَٱلْمُنَـٰفِقِينَ","dan orang-orang munafik"],["وَٱغْلُظْ","dan bersikap tegas"],["عَلَيْهِمْ ۚ","bersama mereka"],["وَمَأْوَىٰهُمْ","Dan tempat tinggal mereka"],["جَهَنَّمُ ۖ","(ialah) Neraka"],["وَبِئْسَ","dan celaka adalah"],["ٱلْمَصِيرُ","destinasi"]]],"5239":["(Allah membuat istri Nuh dan istri Luth perumpamaan bagi orang-orang kafir. Keduanya berada di bawah pengawasan dua orang hamba yang saleh di antara hamba-hamba Kami; lalu kedua istri itu berkhianat kepada kedua suaminya) dalam masalah agama, karena ternyata keduanya kafir dan adalah istri Nabi Nuh yang dikenal dengan nama Wahilah telah berkata kepada kaumnya, \"Sesungguhnya Nuh ini adalah orang gila.\" Sedangkan istri Nabi Luth yang dikenal dengan nama Wailah, memberikan petunjuk kepada kaumnya tentang tamu-tamunya, yaitu bahwa jika tamu-tamu itu tinggal di rumahnya, maka ia akan memberi tanda kepada mereka dengan api di waktu malam dan kalau siang hari dengan memakai asap (maka kedua suaminya itu tiada dapat membantu) yaitu Nabi Nuh dan Nabi Luth tidak bisa menolong (mereka berdua dari Allah) dari azab-Nya (barang sedikit pun; dan dikatakan) kepada kedua istri itu (\"Masuklah kamu berdua ke dalam neraka bersama orang-orang yang memasukinya\") yaitu bersama orang-orang kafir dari kalangan kaum Nabi Nuh dan kaum Nabi Luth.",[["ضَرَبَ","Hadiah"],["ٱللَّهُ","Allah"],["مَثَلًۭا","satu contoh"],["لِّلَّذِينَ","bagi mereka yang"],["كَفَرُوا۟","tidak beriman"],["ٱمْرَأَتَ","(si) isteri"],["نُوحٍۢ","(daripada) Nuh"],["وَٱمْرَأَتَ","(dan) isteri"],["لُوطٍۢ ۖ","(dari) Lut"],["كَانَتَا","Mereka"],["تَحْتَ","bawah"],["عَبْدَيْنِ","dua [budak]"],["مِنْ","daripada"],["عِبَادِنَا","hamba kita"],["صَـٰلِحَيْنِ","soleh"],["فَخَانَتَاهُمَا","tetapi mereka berdua mengkhianati mereka"],["فَلَمْ","jadi tidak"],["يُغْنِيَا","mereka mendapat faedah"],["عَنْهُمَا","mereka berdua"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَقِيلَ","dan dikatakan"],["ٱدْخُلَا","Masuk"],["ٱلنَّارَ","neraka"],["مَعَ","dengan"],["ٱلدَّٰخِلِينَ","mereka yang masuk"]]],"5240":["(Dan Allah membuat istri Firaun perumpamaan bagi orang-orang yang beriman) istri Firaun itu beriman kepada Nabi Musa, ia bernama Asiah. Lalu Firaun menyiksanya dengan cara mengikat kedua tangan dan kedua kakinya, lalu di dadanya diletakkan kincir yang besar, kemudian dihadapkan kepada sinar matahari yang terik. Bilamana orang yang diperintahkan oleh Firaun untuk menjaganya pergi maka, malaikat menaunginya dari sengatan sinar matahari (ketika ia berkata) sewaktu dalam keadaan disiksa (\"Ya Rabbku! Bangunlah untukku sebuah rumah di sisi-Mu dalam surga) maka Allah menampakkan rumahnya yang di surga itu, hingga ia dapat melihatnya, maka siksaan yang dialaminya itu terasa ringan baginya setelah melihat pahalanya (dan selamatkanlah aku dari Firaun dan perbuatannya) dari siksaannya terhadap diriku (dan selamatkanlah aku dari kaum yang lalim.\") yakni pemeluk agama Firaun. Setelah itu lalu Allah mencabut rohnya. Menurut Ibnu Kaisan, bahwa Siti Asiah diangkat ke surga dalam keadaan hidup, dan ia makan dan minum di dalam surga.",[["وَضَرَبَ","Dan hadiah"],["ٱللَّهُ","Allah"],["مَثَلًۭا","satu contoh"],["لِّلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","dipercayai"],["ٱمْرَأَتَ","(si) isteri"],["فِرْعَوْنَ","(daripada) Firaun"],["إِذْ","apabila"],["قَالَتْ","katanya"],["رَبِّ","Tuhanku"],["ٱبْنِ","bina"],["لِى","untuk aku"],["عِندَكَ","dekat Kamu"],["بَيْتًۭا","sebuah rumah"],["فِى","dalam"],["ٱلْجَنَّةِ","Syurga"],["وَنَجِّنِى","dan selamatkan aku"],["مِن","daripada"],["فِرْعَوْنَ","Firaun"],["وَعَمَلِهِۦ","dan perbuatannya"],["وَنَجِّنِى","dan selamatkan aku"],["مِنَ","daripada"],["ٱلْقَوْمِ","manusia"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"5241":["(Dan Maryam) lafal ini diathafkan kepada lafaz imra'atu fir`auna (putri Imran yang memelihara kehormatannya) menjaga kehormatannya (maka Kami tiupkan ke dalam rahimnya sebagian dari roh Kami) yakni malaikat Jibril, ia meniupkan ke dalam kerah bajunya roh ciptaan Allah berdasarkan perintah dari Allah, hingga tiupan itu masuk ke dalam kemaluannya, lalu setelah itu Maryam mengandung Isa (dan dia membenarkan kalimat-kalimat Rabbnya) yakni syariat-syariat-Nya (dan Kitab-kitab-Nya) yang telah diturunkan (dan adalah dia termasuk orang-orang yang taat) termasuk golongan orang-orang yang taat kepada Allah.",[["وَمَرْيَمَ","Dan Maryam"],["ٱبْنَتَ","(si) anak perempuan"],["عِمْرَٰنَ","(dari) Imran"],["ٱلَّتِىٓ","yang"],["أَحْصَنَتْ","terjaga"],["فَرْجَهَا","kesuciannya"],["فَنَفَخْنَا","jadi Kami bernafas"],["فِيهِ","ke dalamnya"],["مِن","daripada"],["رُّوحِنَا","Roh kita"],["وَصَدَّقَتْ","Dan dia beriman"],["بِكَلِمَـٰتِ","(dalam) Perkataan"],["رَبِّهَا","(dari) Tuhannya"],["وَكُتُبِهِۦ","dan Kitab-kitabNya"],["وَكَانَتْ","dan dia"],["مِنَ","daripada"],["ٱلْقَـٰنِتِينَ","yang taat setia"]]]});